import type { A1Module, Lesson } from "@/lib/course";

type PhraseSeed = [english: string, portuguese: string, note: string];
type ExampleSeed = [english: string, portuguese: string];
type QuestionSeed = [prompt: string, options: [string, string, string], answer: number, explanation: string];
type LessonSeed = {
  id: string; title: string; subtitle: string; objective: string; focus: string; intro: string;
  phrases: [PhraseSeed, PhraseSeed, PhraseSeed, PhraseSeed]; grammarTitle: string; grammar: string;
  examples: [ExampleSeed, ExampleSeed, ExampleSeed, ExampleSeed];
  practice: [QuestionSeed, QuestionSeed, QuestionSeed, QuestionSeed]; takeaway: string;
};

function makeLesson(seed: LessonSeed): Lesson {
  return {
    id: seed.id, slug: seed.id, title: seed.title, subtitle: seed.subtitle,
    objective: seed.objective, duration: 16, focus: seed.focus, intro: seed.intro,
    phrases: seed.phrases.map(([english, portuguese, note]) => ({ english, portuguese, note })),
    grammar: { title: seed.grammarTitle, explanation: seed.grammar, examples: seed.examples.map(([english, portuguese]) => ({ english, portuguese })) },
    practice: seed.practice.map(([prompt, options, answer, explanation]) => ({ prompt, options, answer, explanation })),
    takeaway: seed.takeaway,
  };
}

const seeds: LessonSeed[] = [
  {
    id:"rhythm-and-emphasis", title:"The shape of a sentence", subtitle:"Use ritmo e ênfase para orientar a interpretação.", objective:"Reescrever uma frase para destacar informação nova ou contrastiva e explicar como ordem, extensão e pontuação alteram o foco sem mudar os fatos.", focus:"Ritmo, foco e ênfase", intro:"Na revisão de um discurso, duas versões podem comunicar o mesmo fato e, ainda assim, conduzir a atenção a lugares diferentes. “The board approved the plan yesterday” põe a decisão em primeiro plano; “It was yesterday that the board approved the plan” destaca o momento. Em texto, extensão de frase, posição de informação e pontuação criam ritmo; na fala, pausas e proeminência também contam. A escolha não é ornamento: pode esclarecer contraste, criar expectativa ou soar teatral demais. Compare o efeito com a finalidade e o público.",
    phrases:[["What matters here is the timing, not the outcome.","O que importa aqui é o momento, não o resultado.","A estrutura what matters is põe o critério em foco; a oposição fica explícita."],["Only after the audit did the discrepancy become apparent.","Só depois da auditoria a discrepância se tornou evidente.","Only no início pede inversão auxiliar-sujeito em registro formal; use com parcimônia."],["The proposal is workable—just not at this scale.","A proposta é viável — só não nesta escala.","A pausa tipográfica separa concessão e limite, criando uma correção deliberada."],["Not the figures, but their interpretation, needs revisiting.","Não os números, mas sua interpretação, precisa ser revista.","O contraste corrige o foco; a concordância segue o núcleo singular interpretation."]],
    grammarTitle:"Ênfase por ordem, inversão e segmentação", grammar:"O inglês tende à ordem sujeito-verbo-objeto, mas pode deslocar foco. Uma construção cleft (It is/was X that...) destaca um constituinte; fronting antepõe informação para contraste. Depois de expressões negativas ou restritivas como only after, rarely e not until, a oração principal pode exigir inversão (Only then did we understand), sobretudo em prosa formal. A inversão não se aplica automaticamente a toda frase com only: compare Only then did… com Only the chair objected. Fragmentos e travessões podem controlar ritmo em escrita ensaística, mas fragmentação excessiva parece afetada. Não use ênfase para insinuar causalidade ou certeza que os fatos não sustentam.",
    examples:[["It was the revised timetable that resolved the overlap, not the extra staffing.","Foi o cronograma revisado que resolveu a sobreposição, não o reforço de equipe."],["Rarely have the two departments agreed on a single measure.","Raramente os dois departamentos concordaram com uma única medida."],["The report is concise; the implications are not.","O relatório é conciso; as implicações, não."],["What the survey captures is reported experience, not every user's actual access.","O que a pesquisa capta é a experiência relatada, não o acesso real de cada usuário."]],
    practice:[["Você precisa destacar que a auditoria, e não a reunião, revelou a falha. Qual versão faz isso com clareza?",["It was the audit that revealed the flaw, not the meeting.","The meeting audit revealed because flaw.","The flaw was certainly caused by the audit."],0,"A cleft destaca audit e a oposição limita o foco; a terceira acrescenta uma alegação causal inexistente."],["Complete a inversão formal: “Only when the figures were reconciled ___ the discrepancy.”",["did we notice","we noticed","we did noticed"],0,"Only when no início da oração principal favorece inversão: did + sujeito + verbo base."],["Qual edição cria uma pausa enfática sem acrescentar conteúdo factual?",["The evidence is clear; its scope is narrow.","The evidence is clear and proves everything everywhere.","The evidence, perhaps, maybe, possibly, is clear."],0,"A segmentação contrapõe clareza e alcance; as outras opções exageram ou acumulam hesitação."],["Qual afirmação sobre ritmo é mais precisa?",["A sentence opening can foreground a contrast, but emphasis does not itself prove the claim.","Inversion always makes a sentence more persuasive.","A long sentence is always more formal and accurate."],0,"Forma orienta a atenção, mas não substitui suporte nem adequação de registro."]], takeaway:"Marque a informação que o leitor deve notar; escolha ordem e pausa para esse foco e confira que a ênfase não infla a evidência."
  },
  {
    id:"metaphor-and-framing", title:"The frame changes the view", subtitle:"Analise metáforas e seus efeitos argumentativos.", objective:"Identificar a metáfora dominante em um argumento, explicitar o que ela torna saliente e o que deixa fora, e propor uma formulação alternativa neutra.", focus:"Metáfora, enquadramento e argumento", intro:"Uma equipe descreve uma mudança de política como “a safety net” para algumas pessoas e “a drain on resources” para outras. Nenhuma expressão é apenas decorativa: uma evoca proteção; a outra, perda. Metáforas podem tornar um conceito abstrato inteligível e também transportar pressupostos sobre causa, responsabilidade e solução. Analise o enquadramento sem concluir que a escolha lexical prova intenção manipuladora. Pergunte que aspecto a imagem ilumina, que aspecto obscurece e se uma segunda metáfora mudaria a conversa.",
    phrases:[["The policy is being framed as a safety net.","A política está sendo apresentada como uma rede de proteção.","Framed as indica enquadramento interpretativo, não descrição neutra."],["That image foregrounds protection but obscures eligibility rules.","Essa imagem põe a proteção em primeiro plano, mas obscurece os critérios de elegibilidade.","Foregrounds/obscures nomeiam efeitos de seleção sem atribuir intenção automaticamente."],["A more neutral description would be a transfer scheme.","Uma descrição mais neutra seria um programa de transferência.","Mais neutra não significa universalmente imparcial; define-se pela tarefa analítica."],["The metaphor carries an assumption about who bears the cost.","A metáfora carrega uma premissa sobre quem arca com o custo.","Assumption about torna explícito o pressuposto a examinar."]],
    grammarTitle:"Metáforas gramaticais e linguagem de enquadramento", grammar:"Metaphorically, X is cast as Y / X is framed as Y descreve uma representação sem afirmar que ela é literalmente verdadeira. A nominalização (the erosion of trust) comprime uma relação e pode esconder agente ou processo; recupere-os com perguntas como who eroded trust, and how? Adjetivos avaliativos e verbos de movimento (rescue, burden, unlock) podem orientar julgamento antes da evidência. Em análise, diferencie descrição da expressão, inferência sobre efeito e alegação sobre intenção. Uma paráfrase menos carregada deve preservar o conteúdo verificável, não apagar uma perspectiva relevante.",
    examples:[["Calling the platform a ‘gateway’ suggests access, though it says little about who can enter.","Chamar a plataforma de ‘porta de entrada’ sugere acesso, embora diga pouco sobre quem pode entrar."],["The phrase ‘costly failure’ assigns blame before the review is complete.","A expressão ‘fracasso dispendioso’ atribui culpa antes de a revisão terminar."],["The figures show a decline in use; they do not identify what drove it.","Os números mostram queda no uso; não identificam o que a provocou."],["Replacing ‘rescue’ with ‘provide temporary support’ reduces the heroic framing.","Trocar ‘resgatar’ por ‘oferecer apoio temporário’ reduz o enquadramento heroico."]],
    practice:[["Um comunicado chama um corte orçamentário de “streamlining”. Qual análise é mais responsável?",["The term presents the change as efficiency-oriented; examine which services and groups are affected.","The word proves the writers intend to deceive.","The term is literally a measurement of service quality."],0,"A leitura identifica enquadramento e propõe verificação; intenção não pode ser deduzida só da palavra."],["Qual versão explicita um agente que a nominalização omite em “the removal of the safeguards”?",["The committee removed the safeguards.","The safeguards' removal was removed.","There was a safeguarding removal of removal."],0,"A voz ativa torna committee agente, desde que o contexto confirme essa informação."],["Uma imagem torna custos visíveis e exclui benefícios. O que fazer?",["Name both the insight and the omission, then test a different frame.","Assume the metaphor is false in every respect.","Keep the frame because it is memorable."],0,"A análise equilibrada reconhece contribuição e limite do enquadramento."],["Qual par distingue metáfora de fato verificável?",["‘A lifeline’ is a metaphor; the number of recipients is a measurable claim.","Both are equally literal measurements.","A vivid phrase makes its implied statistic true."],0,"A metáfora convida uma interpretação; contagens demandam operacionalização e dados."]],takeaway:"Ao encontrar uma imagem, descreva-a, pergunte o que ilumina e omite e separe efeito retórico de intenção comprovada."
  },
  {
    id:"humor-and-double-meaning", title:"A second meaning", subtitle:"Interprete humor, ambiguidade e duplo sentido.", objective:"Interpretar um efeito de humor ou ambiguidade a partir de pistas contextuais, distinguir leituras possíveis e selecionar uma resposta que não imponha uma intenção incerta.", focus:"Ambiguidade, ironia e humor", intro:"Num grupo de trabalho, alguém escreve “Well, that went swimmingly” depois de uma demonstração em que o projetor falhou e a reunião atrasou. A frase pode ser irônica; fora do contexto, poderia ser elogio literal. Humor depende de conhecimento compartilhado, timing e relação entre participantes. Duplo sentido também pode ser acidental, e uma leitura espirituosa não é necessariamente apropriada em toda situação. Em vez de decodificar uma expressão isolada, reúna pistas e considere o risco de interpretar errado, sobretudo em comunicação intercultural ou escrita assíncrona.",
    phrases:[["I take it that was meant ironically.","Entendo que isso foi dito com ironia.","I take it apresenta interpretação provisória e deixa espaço para correção."],["The line works on two levels.","A frase funciona em dois sentidos.","On two levels nomeia ambiguidade sem decidir qual leitura prevalece."],["The joke depends on a shared reference.","A piada depende de uma referência compartilhada.","Shared reference explica por que uma alusão pode falhar para parte da audiência."],["I may be missing the reference—what does it allude to?","Talvez eu não esteja reconhecendo a referência — a que ela alude?","May sinaliza humildade sem fingir que entendeu."]],
    grammarTitle:"Ambiguidade lexical e leitura pragmática", grammar:"Uma palavra polissêmica admite sentidos relacionados; um trocadilho explora sentidos distintos ou sons parecidos. A ironia pode surgir de incongruência entre avaliação literal e situação. Marcadores como apparently, sure e well não são sinais infalíveis: entonação, sequência conversacional e conhecimento partilhado pesam. Para registrar uma hipótese, use may be intended as / could be read as; para pedir reparo, What do you mean by…? evita atribuir propósito. Citações, emojis e pontuação mudam a leitura em mensagens, mas variam por comunidade. Evite ensinar uma interpretação única quando o contexto não a determina.",
    examples:[["‘That was subtle,’ he said as the announcement flashed across every screen.","‘Isso foi discreto’, disse ele quando o anúncio apareceu em todas as telas."],["The word ‘draft’ could mean a preliminary text or a current of air here.","A palavra ‘draft’ pode significar rascunho ou corrente de ar neste contexto."],["If the joke relies on local slang, some listeners may not catch it.","Se a piada depende de gíria local, alguns ouvintes talvez não a entendam."],["I heard the comment as teasing rather than criticism, but please correct me.","Entendi o comentário como brincadeira, não crítica, mas me corrija se entendi errado."]],
    practice:[["Após uma falha evidente, alguém diz “Flawless execution.” Qual inferência é mais calibrada?",["The contrast could make it ironic; tone and relationship would help confirm that reading.","It is definitely sincere because the words are positive.","The speaker is certainly hostile."],0,"Contraste sustenta hipótese irônica; não basta para afirmar sinceridade ou hostilidade."],["Qual pergunta melhor esclarece um trocadilho desconhecido?",["I may be missing the wordplay—what are the two meanings?","That joke is objectively bad.","You meant to insult me, didn't you?"],0,"A pergunta explicita a lacuna sem atribuir intenção."],["O humor depende de uma referência cultural que parte do público não conhece. Qual revisão ajuda?",["Add brief context or choose a joke that does not require the reference.","Assume everyone shares the same background.","Explain the joke only after the audience objects."],0,"Contexto ou alternativa reduzem exclusão, embora explicar demais possa mudar o efeito."],["Que distinção é correta?",["A possible reading is an inference; the wording alone may not establish the writer's intent.","Any ambiguity proves deliberate deception.","A dictionary entry determines every joke's meaning."],0,"Intenção depende de evidência contextual, não só de possibilidade lexical."]],takeaway:"Trate humor como leitura contextual, não como certeza: use pistas, considere outra interpretação e peça esclarecimento com leveza."
  },
  {
    id:"voice-across-genres", title:"One voice, different genres", subtitle:"Adapte voz autoral entre gêneros e públicos.", objective:"Transformar uma mesma informação em resumo executivo, nota pública e comentário reflexivo, preservando os fatos e adaptando foco, densidade e voz ao gênero.", focus:"Gênero, voz e propósito", intro:"Uma equipe concluiu um teste de seis semanas, observou menos solicitações duplicadas e ainda não comparou custos de suporte. A direção precisa de uma decisão e de uma ressalva; usuários precisam saber o que muda e quando; um relatório analítico precisa situar método e limite. Não basta trocar palavras formais por simples. Cada gênero cria expectativas sobre estrutura, autoria, detalhe e ação. Pratique manter o núcleo factual enquanto muda o que vem primeiro e como o leitor pode usar a informação.",
    phrases:[["For decision-makers, the key question is whether to extend the trial.","Para quem decide, a questão central é se o teste deve ser ampliado.","Põe a decisão em foco, sem afirmar que a ampliação já foi aprovada."],["The trial recorded fewer duplicate requests over six weeks.","O teste registrou menos solicitações duplicadas ao longo de seis semanas.","Recorded atribui a observação ao teste; não especifica causa."],["Support costs have not yet been compared.","Os custos de suporte ainda não foram comparados.","Nomeia um dado ausente que pode afetar a decisão."],["Here is what changes for current users.","Veja o que muda para os usuários atuais.","Fala diretamente ao público e promete informação prática, não persuasão vaga."]],
    grammarTitle:"Estrutura informacional conforme o gênero", grammar:"Resumo executivo costuma começar pela decisão, síntese e risco; aviso público começa pelo que o leitor precisa saber e fazer; análise acadêmica explicita questão, método, achado e limite. A voz ativa nomeia agente quando ele importa; passiva pode centrar resultado, mas não deve ocultar responsabilidade relevante. Use headings e frases-tema como sinalização, não como substitutos de coesão. Preserve tempos, números, grupos e grau de certeza entre versões. Uma voz consistente pode sobreviver à mudança de gênero se critérios, atribuição e cuidado permanecerem, ainda que a extensão e o vocabulário mudem.",
    examples:[["Decision: extend the trial only if support costs can be reviewed before renewal.","Decisão: ampliar o teste somente se os custos de suporte puderem ser revisados antes da renovação."],["Over six weeks, duplicate requests fell; the trial did not assess support costs.","Ao longo de seis semanas, solicitações duplicadas diminuíram; o teste não avaliou custos de suporte."],["We are reviewing the results before confirming whether the service will continue.","Estamos revisando os resultados antes de confirmar se o serviço continuará."],["The reduction is encouraging, but the design does not establish what produced it.","A redução é animadora, mas o desenho não estabelece o que a produziu."]],
    practice:[["Para um aviso aos usuários, qual abertura prioriza utilidade prática?",["Here is what changes for you from Monday, and what remains unchanged.","A six-week observational record was generated.","The decision architecture exhibits multiple dimensions."],0,"O aviso começa pela mudança relevante e antecipa informação acionável."],["Ao converter resultado em nota executiva, o que precisa permanecer?",["The measured period, finding, decision condition, and unresolved cost question.","Every sentence in its original order.","A guarantee of success to sound confident."],0,"O gênero muda foco, mas fatos, limite e condição são estáveis."],["Qual versão evita inferir causa?",["Duplicate requests fell during the trial; the design does not establish why.","The trial eliminated duplicates because it was effective.","The trial proved the service works everywhere."],0,"A primeira relata associação temporal sem causa demonstrada."],["Qual papel a voz passiva pode exercer?",["Center a result when the agent is not the point, while retaining accountability where relevant.","Make any claim more objective by default.","Remove the need to identify who made a decision."],0,"A passiva organiza foco, mas não confere neutralidade automática nem justifica omissões."]],takeaway:"Antes de adaptar, identifique gênero, leitor e ação; depois confira que evidência, período, condição e incerteza sobreviveram à reescrita."
  },
  {
    id:"style-imitation-with-purpose", title:"Borrowing a style consciously", subtitle:"Reconheça e pratique convenções estilísticas com intenção.", objective:"Identificar três recursos observáveis de um estilo (sintaxe, ritmo, léxico ou perspectiva) e usá-los em um texto próprio sem copiar formulações nem caricaturar uma voz ou grupo.", focus:"Estilo, imitação e ética", intro:"Uma editora pede um texto curto que evoque a concisão de um editorial, mas não quer uma cópia de uma colunista específica. A tarefa é identificar escolhas transferíveis — frases curtas após uma oração longa, verbos concretos, contraste controlado — e decidir quais servem ao novo assunto. Estilo não é uma lista de adjetivos nem uma identidade fixa. Imitar um gênero pode ser exercício útil; imitar a voz identificável de uma pessoa viva para confundir leitores, ou transformar variedade linguística em caricatura, traz riscos éticos. Nomeie o recurso e o propósito da escolha.",
    phrases:[["The effect comes from contrast, not from grand vocabulary.","O efeito vem do contraste, não de vocabulário grandioso.","Compara recursos verificáveis, sem tratar raridade lexical como estilo."],["I borrowed the sentence pattern, not the wording.","Tomei emprestado o padrão de frase, não a formulação.","Distingue convenção estrutural de reprodução textual."],["The voice is brisk, with a deliberate pause before the qualification.","A voz é ágil, com uma pausa deliberada antes da ressalva.","Brisk descreve ritmo; a ressalva continua visível."],["This is an homage to a genre, not an attempt to impersonate its author.","É uma homenagem a um gênero, não uma tentativa de se passar por seu autor.","Torna explícita a diferença ética entre convenção e falsa autoria."]],
    grammarTitle:"Recursos estilísticos observáveis", grammar:"Analise escolhas concretas: parataxe (orações coordenadas e ritmo acelerado), hipotaxe (subordinação e hierarquia), paralelismo, comprimento de frase, dêixis, densidade nominal e distribuição de informação. Ao experimentar, mantenha um traço por vez e leia em voz alta; uma combinação excessiva vira pastiche. A escolha lexical traz registro e conotações, não apenas denotação. Atribuição e contexto importam: não apresente texto imitado como obra autêntica nem reproduza marcas de uma comunidade como adereço cômico. Explique o efeito pretendido e confira se a forma serve ao conteúdo.",
    examples:[["The queue grew. The explanation did not.", "A fila cresceu. A explicação, não."],["Although the proposal is affordable in the first year, its maintenance costs remain uncertain.", "Embora a proposta seja acessível no primeiro ano, seus custos de manutenção seguem incertos."],["We tested the route, measured the delay, and published the limitation.", "Testamos o percurso, medimos o atraso e publicamos a limitação."],["A crowded sentence can mirror a crowded timetable—but only if the reader can still follow it.", "Uma frase congestionada pode espelhar um cronograma congestionado — desde que o leitor ainda consiga acompanhá-la."]],
    practice:[["Qual plano de imitação é mais ético e instrutivo?",["Study a genre's sentence patterns and adapt selected features to an original topic.","Copy a living writer's distinctive turns and publish under their name.","Use a dialect as comic shorthand for a social group."],0,"O primeiro trabalha convenções sem confundir autoria ou caricaturar identidades."],["Parataxe tende a…",["place clauses side by side, often creating a brisk, cumulative rhythm","embed every idea in several subordinate clauses","remove all verbs from a passage"],0,"Parataxe coordena unidades; o efeito depende de contexto e pontuação."],["O que testar ao revisar um experimento estilístico?",["Whether each borrowed feature serves meaning and remains legible aloud.","Whether the text contains the rarest possible words.","Whether every sentence has identical length."],0,"Legibilidade e função são critérios mais úteis que ostentação ou uniformidade."],["Como evitar pastiche?",["Select a small number of observable devices and change the subject, wording, and perspective.","Stack every trait associated with a writer.","Assume style is only a matter of accent."],0,"Seleção limitada preserva controle e evita uma imitação mecânica."]],takeaway:"Escolha um recurso formal, diga que efeito ele deve produzir e revise se a experiência é legível, original e respeitosa."
  },
  {
    id:"dialect-and-identity", title:"Many Englishes", subtitle:"Discuta variação sem tratar um sotaque como padrão universal.", objective:"Comparar duas variedades ou registros de inglês descrevendo traços observáveis, contexto de uso e efeitos de inteligibilidade sem hierarquizar falantes por sotaque.", focus:"Variação, identidade e inteligibilidade", intro:"Em uma conferência internacional, participantes usam pronúncias, expressões e convenções diferentes. Um formulário pede “native-like English”, mas não explica se o objetivo é inteligibilidade, consistência editorial ou uma variedade local. Inglês é usado por comunidades diversas; repertórios variam por região, história, profissão e situação. Isso não significa que toda forma funcione igualmente em todo contexto: expectativas institucionais existem e podem ser negociadas. Aprenda a descrever o traço e a necessidade comunicativa sem confundir familiaridade com correção universal.",
    phrases:[["Which variety does the style guide follow?","Qual variedade o guia de estilo segue?","Pergunta por convenção editorial específica, em vez de padrão naturalizado."],["The pronunciation is unfamiliar to me, but the meaning is clear.","A pronúncia não me é familiar, mas o sentido está claro.","Separa familiaridade do interlocutor e inteligibilidade da mensagem."],["Could we agree on a house style for this publication?","Podemos combinar um padrão editorial para esta publicação?","House style é convenção local, não medida de competência geral."],["That expression is common in some contexts, though not universal.","Essa expressão é comum em alguns contextos, embora não seja universal.","Evita converter observação contextual em generalização sobre todos os falantes."]],
    grammarTitle:"Variação linguística e descrição", grammar:"Descreva variação em eixos distintos: fonológico (pronúncia), lexical, gramatical, pragmático e ortográfico. Um traço pode ser sistemático numa variedade e não aparecer noutra; diferença não equivale por si só a erro. Standard English costuma designar convenções codificadas para contextos institucionais, mas há variedades padrão plurais e guias específicos. “Intelligible to this audience” é uma meta situada, não sinônimo de “nativo”. Em edição, defina a convenção necessária e aplique-a consistentemente; em avaliação, use critérios ligados à tarefa e não penalize identidade ou sotaque quando não afetam o objetivo.",
    examples:[["The speakers use different terms for the same administrative role.","Os falantes usam termos diferentes para a mesma função administrativa."],["For this journal, we will follow its stated spelling conventions.","Para este periódico, seguiremos as convenções ortográficas declaradas."],["A listener unfamiliar with the term may need a brief definition.","Um ouvinte não familiarizado com o termo talvez precise de uma definição breve."],["The accent differs from mine; the instructions remain fully intelligible.","O sotaque difere do meu; as instruções continuam plenamente inteligíveis."]],
    practice:[["Um avaliador chama uma pronúncia de “wrong” porque não é a que conhece. Qual resposta melhora a avaliação?",["Specify the task's intelligibility criterion and check whether listeners can follow the key information.","Assume unfamiliar accents are inherently unclear.","Replace the speaker's identity with a more familiar one."],0,"A primeira relaciona avaliação à tarefa e à compreensão observável."],["O que uma house style normalmente faz?",["Sets local editorial conventions for a publication or organization.","Defines the only legitimate English worldwide.","Measures a writer's intelligence."],0,"É uma convenção situada para consistência editorial."],["Como descrever uma diferença linguística?",["Name the feature, variety or context where it occurs, and any task-relevant effect.","Call it broken English without examples.","Infer the speaker's education from accent alone."],0,"Descrição observável evita rótulos e inferências sociais sem base."],["Uma expressão é corrente numa região e desconhecida em outra. Qual edição ajuda leitores diversos?",["Retain it where voice matters and add context if the audience needs it.","Claim that no one uses it.","Remove every regional expression from all writing."],0,"A decisão depende de voz, audiência e necessidade de compreensão."]],takeaway:"Descreva traço e contexto antes de avaliá-lo; defina convenções locais e use inteligibilidade ligada à tarefa, não ideal de sotaque."
  },
  {
    id:"pragmatics-and-face", title:"What a request does", subtitle:"Analise relações, intenção e cortesia em pedidos.", objective:"Reformular um pedido para tornar ação, prazo e opção de recusa claros, ajustando imposição e relação sem depender apenas de fórmulas indiretas.", focus:"Pragmática, pedidos e face", intro:"Uma mensagem ao colega diz “I was wondering whether you might possibly have a look at this when you get a chance.” O tom parece brando, mas não informa qual parte precisa de revisão nem quando. Em outro contexto, uma ordem curta pode soar adequada durante uma emergência e rude numa solicitação rotineira. Cortesia não é sinônimo de rodeios: envolve custo, poder, urgência, relação e clareza. Observe o que o enunciado faz — pedir, oferecer saída, pressionar ou preservar autonomia — e ajuste esses elementos conscientemente.",
    phrases:[["Could you review the final paragraph by noon tomorrow?","Você poderia revisar o parágrafo final até amanhã ao meio-dia?","Pedido cortês com ação e prazo verificáveis."],["If your schedule allows, a brief review would help.","Se sua agenda permitir, uma revisão breve ajudaria.","A condição sinaliza opção real apenas se a recusa não acarretar penalidade oculta."],["Would you be able to take this on, or should I find another reviewer?","Você conseguiria assumir isso ou devo procurar outra pessoa para revisar?","Oferece alternativa explícita e facilita uma resposta honesta."],["I need your decision today because the booking closes at five.","Preciso da sua decisão hoje porque as reservas fecham às cinco.","Explica urgência; clareza pode ser mais respeitosa que indireção prolongada."]],
    grammarTitle:"Atos de fala, mitigação e imposição", grammar:"Can/could you…? e Would you mind + -ing? são formatos comuns, mas a forma interrogativa não garante pedido leve: Could you finish this in ten minutes? pode ser impositivo. Mitigadores (perhaps, a little, if possible) diminuem compromisso ou força; excesso pode obscurecer ação e prazo. Uma solicitação completa nomeia tarefa, motivo quando relevante, prazo e possibilidade genuína de recusa ou negociação. Em relações assimétricas, “no pressure” só funciona se a pessoa realmente puder dizer não. Compare efeito provável, não uma hierarquia fixa de fórmulas.",
    examples:[["Please stop the machine now; the guard is loose.","Pare a máquina agora, por favor; a proteção está solta."],["Might I borrow your notes from yesterday's seminar?","Posso pegar emprestadas suas anotações do seminário de ontem?"],["Could we move the review to Friday, given the new deadline?","Podemos transferir a revisão para sexta, considerando o novo prazo?"],["You are welcome to decline; I can ask the wider team.","Fique à vontade para recusar; posso consultar a equipe toda."]],
    practice:[["Um pedido precisa de revisão até amanhã, mas a pessoa pode recusar. Qual mensagem combina clareza e autonomia?",["Could you review the opening by noon tomorrow? If you cannot, I can ask someone else.","Whenever, maybe, if you happen to feel like it, look at something.","You must do this tonight; no explanation."],0,"A ação e o prazo são claros, e há uma alternativa explícita."],["Por que “Could you do this immediately?” ainda pode soar impositivo?",["Because urgency and the cost of the action matter beyond the grammatical form.","Because could is always rude.","Because questions cannot function as requests."],0,"A pragmática depende de contexto e custo, além da forma interrogativa."],["Em uma emergência de segurança, qual pedido é mais apropriado?",["Move away from the door now; the alarm is sounding.","I was wondering whether perhaps you might move eventually.","Would it be convenient to consider a possible change?"],0,"A urgência justifica uma instrução direta, com razão concreta."],["Qual critério distingue mitigação útil de evasão?",["The listener can still identify the requested action, timing, and whether refusal is possible.","The request contains the most hedges.","The speaker never states a deadline."],0,"Mitigação eficaz preserva informação necessária e autonomia real."]],takeaway:"Calibre o pedido pelo custo, urgência e relação; seja explícito sobre ação e prazo e só ofereça recusa quando ela for genuína."
  },
  {
    id:"translation-loss-and-choice", title:"What cannot be carried over", subtitle:"Compare escolhas de tradução e perdas de nuance.", objective:"Comparar duas traduções possíveis de uma expressão, identificar ganho e perda de registro, implicação ou ritmo e justificar uma escolha conforme público e finalidade.", focus:"Tradução, equivalência e nuance", intro:"Uma mediadora precisa traduzir “That’s a rather ambitious timeline” numa reunião tensa. “É um cronograma bastante ambicioso” preserva a forma, mas talvez não o subtexto; “Esse prazo parece apertado” torna a implicação mais direta, mas troca a imagem avaliativa. Tradução não é correspondência palavra por palavra nem licença para reescrever qualquer coisa. O que conta como equivalência depende de gênero, interlocutores, consequência e propósito. Compare opções explicitando o que cada uma conserva e sacrifica, em vez de chamar uma delas simplesmente de literal ou correta.",
    phrases:[["A close translation preserves the image but not necessarily the tone.","Uma tradução próxima preserva a imagem, mas não necessariamente o tom.","Distingue proximidade lexical de efeito pragmático."],["In this exchange, the understatement carries polite skepticism.","Nesta conversa, o eufemismo transmite ceticismo cortês.","A interpretação depende do contexto de interação, não só do dicionário."],["I chose the less literal version to preserve the warning.","Escolhi a versão menos literal para preservar o alerta.","Justifica escolha por função e permite escrutínio."],["The original leaves the agent unspecified; the translation should too.","O original não especifica o agente; a tradução também deveria deixar isso em aberto.","Preserva uma ambiguidade possivelmente significativa, sem criar responsável."]],
    grammarTitle:"Equivalência funcional e escolhas de tradução", grammar:"Compare denotação, conotação, registro, pressupostos, ritmo e implicatura. Uma tradução pode compensar um jogo de palavras em outro ponto, mas deve sinalizar quando essa solução altera foco. Em discurso citado, não atribua à fonte um grau de certeza ausente; em texto operacional, priorize instruções inequívocas. Quando houver alternativas relevantes, use notas do tipo “esta versão preserva X, mas perde Y”. Voz passiva, modalizadores e artigos podem codificar distinções difíceis de transportar. Não há equivalência perfeita universal: há uma decisão justificável para audiência e finalidade, sujeita a revisão por falantes e especialistas do domínio.",
    examples:[["‘She is economical with the truth’ becomes ‘Ela não conta toda a verdade’ in a direct, critical context.","‘Ela não conta toda a verdade’ funciona num contexto direto e crítico."],["The subtitle keeps the pun's comic beat by using a different wordplay.","A legenda mantém o ritmo cômico do trocadilho usando outro jogo de palavras."],["The contract translates ‘may’ as ‘poderá’ only after legal review of its permissive force.","O contrato traduz ‘may’ como ‘poderá’ apenas após revisão jurídica de sua força permissiva."],["The note preserves the ambiguity rather than naming an agent the original never identifies.","A nota preserva a ambiguidade em vez de nomear um agente que o original nunca identifica."]],
    practice:[["Uma expressão inglesa é formalmente elogiosa, mas no contexto expressa dúvida cortês. Como decidir?",["Compare literal sense and contextual effect, then justify which the translation prioritizes.","Choose the dictionary equivalent automatically.","Assume every indirect phrase is sincere praise."],0,"A tradução deve considerar efeito contextual e tornar a prioridade justificável."],["Em instrução de segurança, qual prioridade é mais forte?",["Preserve the action and conditions unambiguously, even if the syntax changes.","Preserve every source-language word order.","Keep an ambiguity that could change behavior."],0,"O gênero operacional exige que a ação seja compreendida com segurança."],["A tradução torna o agente explícito quando o original o omite. Qual é o risco?",["It may assign responsibility unsupported by the source.","It always improves accuracy.","It removes the need for context."],0,"A escolha altera atribuição de responsabilidade e deve ser evitada sem base."],["Qual comentário de tradução é analiticamente útil?",["This version preserves the warning but makes the speaker more direct.","This is better because it sounds nicer.","All other translations are wrong."],0,"Nomeia ganho e perda de efeito, permitindo avaliar a escolha no contexto."]],takeaway:"Compare sentido, tom e implicação; declare o que sua versão prioriza e não acrescente certeza, agente ou intenção ausentes."
  },
  {
    id:"language-and-power", title:"Words and influence", subtitle:"Examine como escolhas linguísticas distribuem autoridade.", objective:"Analisar uma interação institucional identificando quem pode nomear, interromper ou definir critérios e propor uma reformulação que preserve responsabilização e participação.", focus:"Linguagem, autoridade e participação", intro:"Numa audiência pública, a presidência chama as perguntas de uma comunidade de “anecdotal”, mas descreve números da própria instituição como “the evidence”. As palavras podem demarcar que conhecimento conta; a distribuição de turnos também afeta quem consegue responder. Não conclua, por uma frase isolada, que toda autoridade é ilegítima ou que uma intenção está provada. Observe padrões, regras, acesso a dados e consequências. A análise linguística pode mostrar como autoridade é exercida e onde uma interação poderia abrir espaço sem abandonar padrões de evidência.",
    phrases:[["Who gets to define what counts as evidence here?","Quem pode definir o que conta como evidência aqui?","Questiona critério e autoridade decisória, não a capacidade pessoal de alguém."],["The minutes record the interruption but not the response that followed.","A ata registra a interrupção, mas não a resposta que veio depois.","Aponta assimetria documental específica que pode ser verificada."],["Could we apply the same standard to both sources?","Podemos aplicar o mesmo critério às duas fontes?","Propõe consistência sem presumir que fontes sejam idênticas."],["The procedure gives affected residents a chance to reply.","O procedimento dá aos moradores afetados a oportunidade de responder.","Nomeia participação como característica processual observável."]],
    grammarTitle:"Agência, modalidade e enquadramento institucional", grammar:"Compare quem aparece como agente em estruturas ativas e passivas: The panel excluded the testimony / The testimony was excluded. A passiva pode focalizar evento, mas a omissão recorrente do agente merece exame. Should, must e may codificam obrigação, recomendação ou possibilidade; verifique quem tem autoridade para impor cada modalidade. Nominalizações como non-compliance podem transformar uma relação complexa em rótulo sobre pessoas. Analise quem define categorias, quem pode contestá-las e quais consequências seguem; evite inferir intenção discriminatória apenas da gramática, considerando também padrões e contexto institucional.",
    examples:[["The agency rejected the appeal without publishing its criteria.","A agência rejeitou o recurso sem publicar seus critérios."],["The complaint was dismissed; the record does not say who made the decision.","A reclamação foi rejeitada; o registro não informa quem tomou a decisão."],["Residents should be able to challenge the classification before it affects their access.","Moradores deveriam poder contestar a classificação antes que ela afete seu acesso."],["The label ‘non-compliant’ combines several different reasons for missing a deadline.","O rótulo ‘em descumprimento’ combina razões diferentes para perder um prazo."]],
    practice:[["Qual pergunta examina poder de definição sem atacar uma pessoa?",["Who sets the criteria, and how can affected groups challenge them?","Why are the officials dishonest?","Can we ignore who wrote the rules?"],0,"Pergunta por processos verificáveis de definição e contestação."],["Qual par torna visível a diferença de agência?",["The board denied the request. / The request was denied.","The request denied the board. / The board was request.","The denial was denied in denial."],0,"A primeira versão ativa nomeia agente; a passiva focaliza o evento e pode omiti-lo."],["Uma categoria reúne causas distintas de ausência. Qual revisão é mais justa?",["Record the specific reason where possible rather than infer one motive from the label.","Treat every person in the category as identical.","Remove all records of the decision."],0,"Especificidade evita transformar classificação agregada em julgamento individual."],["Que evidência sustenta melhor uma análise de assimetria?",["A repeated pattern of unequal speaking time and documented procedural rules.","One ambiguous phrase interpreted without context.","A guess about an official's private motives."],0,"Padrão e regras permitem examinar consequências sem depender de leitura mental."]],takeaway:"Procure padrões de agência, voz, critério e direito de resposta; sustente alegações sobre poder com evidência contextual."
  },
  {
    id:"c2-contextual-reading", title:"A text in its moment", subtitle:"Interprete um texto em seu contexto cultural e histórico.", objective:"Interpretar um texto relacionando escolhas linguísticas a gênero, audiência e contexto histórico documentado, distinguindo evidência contextual de especulação sobre intenção.", focus:"Contexto histórico, gênero e interpretação", intro:"Uma carta de arquivo descreve um bairro como “improved” depois de uma obra pública. Para leitores atuais, a palavra pode soar favorável; para interpretá-la, precisamos saber quem escreveu, para quem, em que gênero e quais mudanças ocorreram. Contextualizar não significa reduzir cada frase à biografia do autor nem supor que todos os leitores da época pensavam igual. Procure documentos contemporâneos, convenções do gênero e vozes ausentes. Depois explique como esse contexto altera — ou não altera — a leitura, mantendo limites claros para o que não sabemos.",
    phrases:[["The phrase reflects the document's administrative vocabulary.","A expressão reflete o vocabulário administrativo do documento.","Relaciona escolha lexical a gênero sem determinar sua intenção."],["The archive provides context, not a complete account of residents' views.","O arquivo oferece contexto, não um relato completo das opiniões dos moradores.","Distingue fonte contextual de representação total da comunidade."],["At the time, the term was used in a different institutional sense.","Na época, o termo era usado num sentido institucional diferente.","At the time situa a interpretação; o uso precisa ser documentado."],["We should not assume that every reader interpreted it alike.","Não devemos presumir que todos os leitores a interpretaram da mesma forma.","Evita generalização sobre audiência histórica heterogênea."]],
    grammarTitle:"Marcadores de tempo e atribuição interpretativa", grammar:"Expressões como in this 1930s report, according to the minutes e within the genre of a petition delimitam base interpretativa. Distinga “the text says” de “the wording may suggest” e “the archive does not establish”. Past-tense paraphrase não deve transformar vocabulário da fonte em categoria atual sem explicação. Compare versões datadas e leitores possíveis, mas não invente uma reação coletiva. Quando uma palavra mudou de sentido, registre evidência lexicográfica ou documental e preserve incerteza sobre usos individuais.",
    examples:[["In the petition, ‘order’ refers to the stated rules, not necessarily public agreement.","Na petição, ‘ordem’ se refere às regras declaradas, não necessariamente à concordância pública."],["The editor's note identifies the intended audience as municipal officials.","A nota editorial identifica autoridades municipais como público pretendido."],["Later testimony complicates the report's description of the relocation.","Depoimentos posteriores tornam mais complexa a descrição da remoção no relatório."],["The available records cannot tell us how every resident understood the phrase.","Os registros disponíveis não permitem saber como cada morador entendeu a expressão."]],
    practice:[["Um relatório histórico usa um termo hoje contestado. Qual abordagem é mais cuidadosa?",["Quote or contextualize the term, identify its source and date, and explain its present implications.","Silently replace it and present the wording as original.","Assume every reader at the time agreed with it."],0,"Contexto, atribuição e comentário preservam fidelidade e legibilidade crítica."],["O que um arquivo incompleto permite afirmar?",["What its surviving documents record, with limits on whose views they represent.","What every member of the community believed.","The author's private intention with certainty."],0,"Documentos sobreviventes sustentam afirmações limitadas ao registro disponível."],["Qual frase distingue texto de inferência?",["The report calls the district ‘improved’; this may reflect the agency's planning criteria.","The report proves all residents welcomed the change.","The word means exactly what it means today."],0,"A primeira cita a fonte e apresenta interpretação como possibilidade."],["Qual fonte ajuda a confirmar mudança de sentido?",["Dated dictionaries and documents from the relevant period, read alongside context.","A contemporary intuition alone.","An undated social-media comment."],0,"Fontes datadas permitem comparação histórica, ainda sujeita a variação e contexto."]],takeaway:"Ancore leituras em gênero, data e fontes; separe o que o documento diz, o que pode implicar e o que o arquivo não revela."
  },
  {
    id:"surface-hidden-assumptions", title:"The premise beneath the argument", subtitle:"Identifique premissas ocultas sem reduzir a posição alheia.", objective:"Reconstruir um argumento separando conclusão, razões explícitas e ao menos uma premissa não declarada, e testar se a premissa é necessária ou contestável.", focus:"Premissas implícitas e reconstrução caridosa", intro:"Numa reunião, alguém afirma: “We should move all consultations online; it will save travel time.” A conclusão parece apoiada por uma razão, mas talvez dependa da premissa de que todas as pessoas conseguem acessar e usar a plataforma. Reconstruir pressupostos não é caçar falácias nem atribuir crenças ocultas como fato. Formule a premissa mínima que conectaria razão e conclusão, procure uma alternativa e pergunte ao interlocutor se a reconstrução é justa. Assim, a crítica incide na ponte lógica, não numa caricatura da posição.",
    phrases:[["The conclusion seems to rely on the assumption that…","A conclusão parece depender da premissa de que…","Seems to deixa a reconstrução aberta à correção."],["If I have understood the reasoning, the missing link is…","Se entendi o raciocínio, o elo que falta é…","Nomeia a ligação entre razão e conclusão sem declarar que a pessoa a endossa conscientemente."],["Would the recommendation still hold if that condition were absent?","A recomendação ainda se sustentaria se essa condição não existisse?","Testa necessidade da premissa com um cenário alternativo."],["I may be reconstructing your argument too strongly; is this fair?","Talvez eu esteja reconstruindo seu argumento de forma forte demais; isso é justo?","Convite explícito para corrigir paráfrase evita espantalho."]],
    grammarTitle:"Condicionais para testar premissas", grammar:"A reconstrução distingue premissa expressa e warrant: a inferência que liga razão a conclusão. Use if… then… para tornar a ligação visível; unless testa condição necessária; even if explora se a conclusão sobrevive a uma concessão. Uma pergunta indireta (Could you explain why the finding supports that policy?) mantém ordem sujeito-verbo na oração encaixada. Evite afirmar “you assume” quando a premissa é apenas necessária para a leitura; prefira the argument appears to rely on. Uma premissa pode ser plausível e ainda precisar de evidência.",
    examples:[["If the service is meant to reach every resident, access needs to be part of the design.","Se o serviço pretende alcançar todos os moradores, o acesso precisa fazer parte do projeto."],["Even if the pilot saves time, it may not reduce total costs.","Mesmo que o piloto economize tempo, talvez não reduza os custos totais."],["Could you explain how the survey result supports a permanent change?","Você poderia explicar como o resultado da pesquisa sustenta uma mudança permanente?"],["The recommendation depends on comparable outcomes across the two sites.","A recomendação depende de resultados comparáveis entre os dois locais."]],
    practice:[["Argumento: “We should extend opening hours because evening attendance is high.” Qual premissa conecta razão e conclusão?",["High evening attendance indicates unmet demand that longer hours could address.","Every resident prefers evening hours.","The building is attractive."],0,"A primeira é a ponte mínima, mas ainda precisaria de teste e delimitação."],["Qual abertura reconstrói sem atribuir crença como certeza?",["The proposal seems to rely on the idea that all users can access the platform.","You assume no one has access problems.","Your argument is irrational."],0,"Seems to rely on marca interpretação provisória e focaliza o argumento."],["O que testa whether uma premissa é necessária?",["Ask whether the conclusion would still follow if the premise were false.","Repeat the conclusion more forcefully.","Ignore the stated reason."],0,"Um contrafactual ajuda a avaliar o papel inferencial da premissa."],["Uma leitura sua não parece justa ao interlocutor. Qual resposta é apropriada?",["Invite correction and restate the claim in terms the speaker recognizes.","Insist that you know their real assumption.","Change the subject to their character."],0,"Reconstrução caridosa é provisória e corrigível." ]],takeaway:"Separe razão, conclusão e ponte inferencial; apresente pressupostos como hipótese e convide correção antes de contestá-los."
  },
  {
    id:"disagree-with-care", title:"A rigorous disagreement", subtitle:"Conteste uma ideia com precisão e respeito.", objective:"Formular uma discordância que represente fielmente a tese alheia, identifique o ponto exato de divergência e ofereça razão ou evidência proporcional.", focus:"Discordância rigorosa e civilidade", intro:"Uma comissão recebe a recomendação de adotar imediatamente um sistema em toda a rede. Você concorda que o piloto foi promissor, mas discorda de generalizar o resultado: o teste envolveu apenas duas unidades. Uma contestação eficaz reconhece a parte sustentada, explicita o salto lógico e propõe o que resolveria a diferença. Ser cordial não exige elogio ritual nem evitar conclusões. Ser rigoroso tampouco exige linguagem agressiva. O foco está em crítica específica, consequência e possibilidade de revisão.",
    phrases:[["I agree that the pilot is promising; I question the proposed scale-up.","Concordo que o piloto é promissor; questiono a ampliação proposta.","Identifica ponto de acordo e objeto exato do desacordo."],["The evidence supports feasibility in two sites, not yet a network-wide effect.","As evidências sustentam viabilidade em dois locais, ainda não um efeito em toda a rede.","Contrasta alcance observado com conclusão mais ampla."],["Could we distinguish the case for a trial from the case for full adoption?","Podemos distinguir o argumento a favor de um teste daquele a favor da adoção integral?","Pergunta separa decisões que exigem suportes diferentes."],["I would revise my view if comparable results emerged elsewhere.","Eu revisaria minha posição se surgissem resultados comparáveis em outros locais.","Indica condição de revisão, tornando a posição testável."]],
    grammarTitle:"Concessão, foco contrastivo e condição de revisão", grammar:"Use I agree that + oração para conceder uma proposição específica; I question whether delimita a dúvida; the evidence supports X, not Y explicita a extensão. Granted pode soar formal ou concessivo; nonetheless deve introduzir a consequência que permanece. Condicionais como I would reconsider if… mostram o que alteraria sua posição. Evite perguntas retóricas que funcionam como acusação. Nomear padrão de evidência não equivale a rejeitar a proposta; se a evidência é preliminar, escolha uma conclusão proporcional como trial rather than adoption.",
    examples:[["Your estimate is internally consistent, though it excludes maintenance after year one.","Sua estimativa é internamente coerente, embora exclua manutenção após o primeiro ano."],["I take the access concern seriously; the proposed metric does not capture it.","Levo a preocupação com acesso a sério; a métrica proposta não a capta."],["The comparison supports a short extension, not a permanent commitment.","A comparação sustenta uma extensão curta, não um compromisso permanente."],["What evidence would distinguish a seasonal effect from a program effect?","Que evidência distinguiria um efeito sazonal de um efeito do programa?"]],
    practice:[["Qual resposta critica o escopo da conclusão sem descartar o achado?",["The result is encouraging in the pilot sites; broader effects remain untested.","The study is useless because it is small.","The system must work everywhere because two sites improved."],0,"A primeira preserva valor local e explicita limite de generalização."],["Complete: “I agree ___ the objective, but question whether this measure will reach it.”",["with","to","for"],0,"Agree with + substantivo identifica o aspecto aceito."],["Qual formulação mostra que você pode revisar sua posição?",["I would reconsider if the comparison included another season.","Nothing could ever change my mind.","I already know the answer."],0,"A condição especifica que evidência seria relevante para revisão."],["A pessoa diz que é preciso agir logo. Qual pergunta distingue duas decisões?",["Could we separate a reversible trial from permanent adoption?","Why are you careless?","Can we avoid discussing consequences?"],0,"A pergunta torna comparáveis alternativas com níveis de compromisso distintos."]],takeaway:"Reconheça o que a evidência sustenta, localize o salto contestado e diga que informação poderia mudar sua posição."
  },
  {
    id:"repairing-misunderstandings", title:"Let’s recalibrate", subtitle:"Repare mal-entendidos e confirme interpretações.", objective:"Interromper uma interpretação equivocada sem escalar conflito, explicitar a leitura recebida, corrigir o ponto e confirmar o entendimento compartilhado.", focus:"Reparo conversacional e alinhamento", intro:"Durante uma reunião remota, a frase “We can revisit the budget next quarter” é entendida como aprovação de gastos adicionais. A pessoa que falou queria apenas adiar a discussão. Mal-entendidos são normais, especialmente com áudio ruim, pronomes vagos e prazos implícitos. Reparar não é provar quem ouviu errado: é localizar a divergência, reformular a mensagem e verificar a consequência prática. Use uma pergunta de checagem quando a decisão depende da interpretação.",
    phrases:[["I may not have been clear: I meant to defer the decision, not approve the spend.","Talvez eu não tenha sido clara: quis adiar a decisão, não aprovar o gasto.","Assume responsabilidade pela clareza sem admitir uma intenção que não teve."],["When you say ‘next quarter’, do you mean the review or the payment?","Quando você diz ‘no próximo trimestre’, quer dizer a revisão ou o pagamento?","Pergunta aponta a ambiguidade concreta."],["Let me check that I have understood you correctly.","Deixe-me confirmar se entendi você corretamente.","Prefácio de paráfrase verificável, não fórmula vazia."],["So no funds are released until the revised estimate is approved—is that right?","Então nenhum recurso será liberado até a estimativa revisada ser aprovada — é isso?","Confirma consequência operacional e condição." ]],
    grammarTitle:"Reformulação, perguntas de checagem e reparo", grammar:"Estruturas de reparo incluem I mean…, Let me rephrase…, Do you mean X or Y? e So, if I understand you… . Perguntas indiretas mantêm ordem normal: Could you clarify what you meant? (não what did you mean dentro da oração encaixada). Contrast markers such as not X but Y delimit correção. Repetir a mensagem mais alto não resolve ambiguidade. Peça confirmação explícita de agente, prazo e decisão quando têm consequência. Em canais escritos, substitua this/that por nomes concretos e registre o acordo após a conversa.",
    examples:[["By ‘approved’, I mean cleared for review, not authorized for purchase.","Com ‘aprovado’, quero dizer liberado para análise, não autorizado para compra."],["Could you clarify whether the deadline applies to the draft or the final version?","Você poderia esclarecer se o prazo se aplica ao rascunho ou à versão final?"],["Let me put that another way: the service remains available while we assess the cost.","Vou formular de outra maneira: o serviço continua disponível enquanto avaliamos o custo."],["We seem to agree on the date; the unresolved point is who sends the notice.","Parece que concordamos sobre a data; o ponto pendente é quem enviará o aviso."]],
    practice:[["Uma pessoa entendeu que sua sugestão já foi aprovada. Como corrigir sem acusação?",["I may not have been clear: I was proposing a review, not confirming approval.","You heard everything wrong.","Fine, then let's pretend it was approved."],0,"A primeira corrige o conteúdo e reduz atribuição de culpa."],["Complete a pergunta indireta: “Could you clarify what the note ___?”",["means","does mean","mean does"],0,"Na oração encaixada, usa-se ordem afirmativa: what the note means."],["Qual checagem é melhor antes de liberar pagamento?",["So the payment waits for written approval—have I understood correctly?","We discussed this, so it is obvious.","I assume everyone agrees."],0,"Repete a consequência concreta e pede confirmação explícita."],["Há acordo sobre data, mas não sobre responsável. Qual síntese é fiel?",["We agree on when; we still need to decide who will send it.","We agree on every detail.","Nothing was agreed."],0,"Distingue convergência e questão ainda aberta."]],takeaway:"Nomeie a leitura que surgiu, corrija com contraste concreto e confirme a consequência que orienta a próxima ação."
  },
  {
    id:"facilitating-conflict", title:"Productive tension", subtitle:"Facilite divergência sem forçar consenso artificial.", objective:"Facilitar uma discussão tensa dando voz a perspectivas distintas, resumindo pontos em termos neutros e registrando decisões, dissensos e questões pendentes separadamente.", focus:"Facilitação, conflito e síntese", intro:"Um grupo discute a realocação de horários: famílias valorizam previsibilidade; equipes valorizam flexibilidade; a administração precisa controlar custos. “Vamos encontrar consenso” pode silenciar diferenças importantes se a decisão já estiver quase tomada. Facilitação C2 não elimina conflito; torna as razões audíveis, verifica se a síntese é reconhecida e define como a decisão será tomada. Um acordo parcial e um dissenso documentado são resultados mais honestos que uma unanimidade presumida.",
    phrases:[["Let me separate the shared concern from the proposed solutions.","Vou separar a preocupação compartilhada das soluções propostas.","Desagrega objetivo comum e alternativas sem fingir que são iguais."],["I hear two priorities: predictability for families and flexibility for staff.","Ouço duas prioridades: previsibilidade para famílias e flexibilidade para a equipe.","Nomeia perspectivas em paralelo; confirme se participantes se reconhecem nessa síntese."],["We have not resolved the cost question.","Ainda não resolvemos a questão do custo.","Marca pendência em vez de forçar encerramento."],["Can we record the disagreement and agree on a review point?","Podemos registrar a divergência e combinar um momento de revisão?","Propõe processo e acompanhamento sem exigir consenso substantivo." ]],
    grammarTitle:"Marcadores de turno, síntese e desacordo", grammar:"Use What I’m hearing is… para uma síntese provisória e invite correction: Have I captured that accurately? Distinga agreement on a goal, agreement on a method e decision by authority. While X prioritizes…, Y is concerned about… mantém paralelismo sem atribuir motivos. One unresolved issue is… registra dissenso. Perguntas abertas podem convidar explicações; em conflito intenso, turnos definidos e pergunta específica podem ser mais inclusivos. Não use nonetheless para apagar uma objeção logo após repeti-la.",
    examples:[["Before we compare options, could each group name its non-negotiable constraint?","Antes de compararmos opções, cada grupo poderia nomear sua restrição inegociável?"],["What I hear is agreement on access, but not on how hours should be allocated.","O que ouço é concordância sobre acesso, mas não sobre como distribuir os horários."],["The cost concern remains unresolved, so the decision is conditional rather than final.","A preocupação com custos segue sem solução, então a decisão é condicional, não final."],["Let us record both the majority recommendation and the dissenting rationale.","Vamos registrar tanto a recomendação majoritária quanto a justificativa dissidente."]],
    practice:[["Duas pessoas discordam sobre método, mas compartilham objetivo. Qual síntese evita falso consenso?",["We share the goal; we differ on the method and should record both views.","Everyone agrees, so no issue remains.","The disagreement means the goal is impossible."],0,"Explicita convergência e desacordo em dimensões separadas."],["Qual pergunta testa se a síntese é fiel?",["Have I captured your concern accurately?","Why are you still upset?","Can we move on without checking?"],0,"Convida correção sem patologizar a reação."],["A questão de custo continua aberta. O que registrar?",["The cost question remains unresolved and will return at the review point.","The group reached full agreement.","Costs do not matter."],0,"Registra pendência e processo de retorno."],["Quando turnos definidos podem ser úteis?",["When several voices are competing and participants need a fair chance to contribute.","Whenever disagreement should be hidden.","Only when one person has nothing to add."],0,"Estrutura pode equilibrar participação em contextos de competição por turno."]],takeaway:"Separe objetivo, solução e autoridade de decisão; valide sua síntese e registre acordo, dissenso e pendências sem os confundir."
  },
  {
    id:"c2-dialogue-lab", title:"A difficult conversation", subtitle:"Conduza diálogo complexo com síntese imparcial.", objective:"Conduzir uma conversa simulada de decisão usando esclarecimento, paráfrase, resposta a objeção e síntese final que distingue acordos e questões não resolvidas.", focus:"Integração de competências dialógicas", intro:"Você modera uma conversa entre uma equipe de pesquisa e uma associação de moradores sobre sensores de ruído. Pesquisadores precisam de dados comparáveis; moradores temem vigilância e usos futuros. Ambos podem ter razões legítimas e interesses distintos. A meta não é declarar vencedora uma parte, nem tratar riscos e benefícios como automaticamente equivalentes. Conduza a conversa: defina o termo contestado, peça evidência e condições, reformule cada posição para confirmação e termine com próximos passos específicos, incluindo o que ainda não foi consentido.",
    phrases:[["When you say ‘anonymous’, what information is retained?","Quando você diz ‘anônimo’, que informações são mantidas?","Transforma termo tranquilizador em pergunta operacional verificável."],["If I have this right, the concern is future use, not only collection.","Se entendi, a preocupação é o uso futuro, não apenas a coleta.","Paráfrase distingue etapas do risco; convide a pessoa a corrigir."],["We can agree on a data-retention limit without agreeing on deployment.","Podemos concordar com um limite de retenção sem concordar com a implementação.","Separa uma salvaguarda de uma decisão maior."],["The next step is to publish the protocol and invite written objections.","O próximo passo é publicar o protocolo e convidar objeções por escrito.","Ação concreta melhora transparência, mas não substitui consentimento necessário."]],
    grammarTitle:"Movimentos conversacionais e registro de decisão", grammar:"Uma sequência útil é: esclarecer termos, parafrasear posições, investigar condições e evidências, separar decisões reversíveis de irreversíveis e sintetizar. Use if I understand you correctly para paráfrase; what would need to be true for…? para condições; we have agreed to X, while Y remains open para fechamento preciso. Diferencie consenso, compromisso processual e decisão por autoridade. Perguntas gramaticalmente polidas podem ainda pressionar; deixe claro se participação é voluntária e quem decide. Registre responsável, prazo e mecanismo de revisão, sem converter silêncio em anuência.",
    examples:[["Does the retention limit cover raw recordings as well as summary data?","O limite de retenção abrange gravações brutas e dados resumidos?"],["The association supports consultation, but has not endorsed data collection.","A associação apoia a consulta, mas não endossou a coleta de dados."],["What evidence would show that the safeguards work in practice?","Que evidência mostraria que as salvaguardas funcionam na prática?"],["We agreed to review the protocol; deployment remains undecided.","Concordamos em revisar o protocolo; a implementação permanece sem decisão."]],
    practice:[["Uma parte diz “the data are anonymous”. Qual pergunta busca precisão operacional?",["Which identifiers are removed, and can records be linked back later?","That sounds reassuring, so no details are needed.","Are you saying privacy never matters?"],0,"Investiga identificadores e possibilidade de reidentificação, sem pressupor resposta."],["Qual fechamento representa fielmente apoio à consulta, mas não à coleta?",["Consultation is supported; data collection has not been approved.","Everyone agreed to proceed.","No one supports any further discussion."],0,"Distingue apoio processual de consentimento substantivo."],["Que resposta demonstra escuta ativa sem apropriar a posição?",["If I understand correctly, you are concerned about future reuse as well as initial collection—is that right?","Your concern is simply resistance to research.","Let's ignore future use and discuss benefits."],0,"Reformula dois aspectos e abre espaço para correção."],["O grupo concordou em revisar protocolo, não em instalar sensores. Como registrar?",["We agreed to review the protocol; deployment remains undecided.","The pilot is approved.","We reached no agreement at all."],0,"A primeira separa compromisso processual da decisão de implementação."]],takeaway:"No encerramento, diga o que foi acordado, o que não foi e quem fará o quê até quando; não trate silêncio como consentimento."
  },
  {
    id:"translate-expertise-for-the-public", title:"Complex ideas, clear language", subtitle:"Adapte explicação especializada sem distorcer conceitos.", objective:"Explicar um conceito especializado a público não especialista em até três passos, mantendo distinção essencial, limite da evidência e uma analogia explicitamente delimitada.", focus:"Mediação de conhecimento especializado", intro:"Uma equipe de saúde pública precisa explicar um intervalo de confiança numa sessão comunitária. Trocar o termo técnico por “margem de erro” pode ajudar, mas também sugerir que o número verdadeiro está garantidamente dentro daquele intervalo. Comunicação clara não é simplificação infantil nem uma avalanche de jargão. Comece pelo que a audiência precisa compreender para decidir, use uma imagem útil e declare onde a comparação deixa de valer. Preserve a diferença conceitual central e convide perguntas sem atribuir dificuldade ao público.",
    phrases:[["In practical terms, this estimate is consistent with a range of plausible values.","Em termos práticos, esta estimativa é compatível com uma faixa de valores plausíveis.","Formulação acessível, mas a interpretação exata depende do método estatístico usado."],["The analogy helps with the idea of spread, not with the study's assumptions.","A analogia ajuda a entender a dispersão, não as premissas do estudo.","Delimita explicitamente o alcance da analogia."],["What this does not tell us is whether the intervention caused the change.","O que isso não nos diz é se a intervenção causou a mudança.","A estrutura destaca limite inferencial relevante."],["Would a concrete example make the distinction clearer?","Um exemplo concreto ajudaria a esclarecer a diferença?","Pergunta à audiência, sem presumir que a explicação falhou por culpa dela."]],
    grammarTitle:"Definição, analogia e ressalva acessíveis", grammar:"Uma explicação eficaz pode seguir: termo e definição curta; exemplo concreto; limite ou não-exemplo. Use in other words para reformular, not to say para marcar uma inferência que não se deve fazer e for example para instanciar sem generalizar. Analogias mapeiam alguns aspectos, não todos: explicite the comparison breaks down when… . Preserve quantificadores, temporalidade e causalidade. Evite “simplesmente” antes de conceito controverso, pois pode ocultar debate metodológico. Verifique compreensão com pergunta substantiva, não “does that make sense?” como teste social.",
    examples:[["A model is a simplified representation; it can clarify patterns while leaving out details.","Um modelo é uma representação simplificada; pode esclarecer padrões e deixar detalhes de fora."],["Think of the forecast as a range of scenarios, not a promise about one outcome.","Pense na previsão como uma faixa de cenários, não uma promessa sobre um resultado."],["The comparison is useful for showing delay, but it does not explain its cause.","A comparação ajuda a mostrar o atraso, mas não explica sua causa."],["Which part would you want us to unpack before discussing the recommendation?","Que parte você gostaria que explicássemos melhor antes de discutir a recomendação?"]],
    practice:[["Uma analogia explica dispersão, mas não premissas do modelo. Qual frase é mais transparente?",["The analogy illustrates spread; it does not capture how the model's assumptions were chosen.","The analogy proves the model is correct.","The audience need not know about assumptions."],0,"A primeira preserva o ganho e declara o limite."],["Qual sequência favorece compreensão sem distorção?",["Brief definition, concrete example, then a relevant limitation.","Five acronyms, no example, universal conclusion.","Analogy presented as exact equivalence."],0,"A sequência constrói entendimento e delimita extrapolação."],["Por que perguntar “Which part should we unpack?” pode ser melhor que “Does that make sense?”",["It invites a specific question without making the listener responsible for reassuring the speaker.","It guarantees comprehension.","It avoids discussing the concept."],0,"Pergunta específica reduz pressão social, embora não prove compreensão por si só."],["Qual formulação preserva cautela causal?",["The pattern is consistent with the intervention having an effect, but other explanations remain possible.","The pattern proves the intervention caused every change.","Nothing can be learned from a pattern."],0,"A primeira comunica compatibilidade e alternativas, sem negar valor da observação."]],takeaway:"Explique o conceito em passos, use analogia com limites explícitos e preserve causalidade, escopo e incerteza originais."
  },
  {
    id:"communicating-risk-and-uncertainty", title:"What might happen", subtitle:"Comunique probabilidades e riscos com calibração.", objective:"Redigir uma comunicação de risco que diferencie probabilidade, gravidade e exposição, declare horizonte temporal e grupo relevante e proponha ação proporcional.", focus:"Risco, probabilidade e calibração", intro:"Um alerta diz que uma falha “is unlikely but could have serious consequences”. Uma pessoa lê unlikely como “não acontecerá”; outra entende serious como certeza de dano grave. Comunicação de risco precisa separar chance, impacto, exposição e período, além de explicar o que se sabe e o que permanece incerto. Evite números sem denominador e adjetivos dramáticos ou tranquilizadores sem contexto. A recomendação deve ser proporcional às consequências e atualizada quando surgirem novos dados.",
    phrases:[["The risk is low over the next month, but not zero.","O risco é baixo no próximo mês, mas não é zero.","Delimita horizonte temporal e impede leitura de impossibilidade."],["The potential impact is serious for people using the affected device.","O impacto potencial é grave para quem usa o dispositivo afetado.","Identifica severidade e grupo exposto, não apenas probabilidade."],["We do not yet have a reliable estimate for this subgroup.","Ainda não temos uma estimativa confiável para este subgrupo.","Nomeia a lacuna sem extrapolar média geral."],["Until the inspection is complete, use the backup process.","Até a inspeção terminar, use o procedimento alternativo.","Conecta incerteza a uma ação temporária e revisável." ]],
    grammarTitle:"Modalizadores, condicionais e risco", grammar:"Diferencie probability (chance), severity (impacto) e exposure (quem ou o que está sujeito). Unlikely não significa impossible; may occur em condições X é mais informativo que could sem cenário. Para números, declare população, período e denominador; não transforme uma taxa em contagem sem base. Use until/while para medidas temporárias e if… then… para condição de atualização. A expressão no evidence of X não equivale a evidence that X is absent. Calibre tom para evitar falsa tranquilização e alarme desproporcional.",
    examples:[["No confirmed cases have been reported this week; reporting may be incomplete.","Nenhum caso confirmado foi relatado esta semana; os relatos podem estar incompletos."],["If the temperature exceeds the threshold, the system will switch to backup power.","Se a temperatura ultrapassar o limite, o sistema passará para energia de reserva."],["The estimate applies to monitored sites, not to every building.","A estimativa se aplica aos locais monitorados, não a todos os edifícios."],["We will reassess the guidance when the inspection data are available.","Reavaliaremos a orientação quando os dados da inspeção estiverem disponíveis."]],
    practice:[["Um evento tem baixa probabilidade, mas alto impacto. Qual comunicação separa dimensões?",["It is unlikely during the next month, but the impact could be severe for exposed users.","It is harmless because it is unlikely.","Severe impact means the event is certain."],0,"A primeira separa chance, prazo e gravidade potencial."],["O relatório diz “no evidence of harm” com dados limitados. O que não se deve inferir automaticamente?",["That harm has been proven absent.","That the review found no supporting evidence in the available data.","That data limitations matter."],0,"Ausência de evidência observada não prova ausência de efeito."],["Como informar taxa de risco de modo interpretável?",["State the numerator, denominator, population, and time period where available.","Give a percentage without context.","Use ‘rare’ for any number below ten."],0,"Denominador, grupo e período tornam a taxa interpretável."],["Qual orientação corresponde a incerteza temporária?",["Use the backup process until the inspection is complete; we will reassess then.","The system is perfectly safe forever.","Stop all activity with no explanation or review date."],0,"A primeira vincula ação a condição observável e revisão futura."]],takeaway:"Comunique chance, impacto, grupo e horizonte separadamente; explicite lacunas e associe precaução a condição e revisão."
  },
  {
    id:"defending-a-method", title:"Why this method?", subtitle:"Justifique escolhas metodológicas e suas limitações.", objective:"Defender uma escolha metodológica por sua adequação à pergunta, explicitar ao menos uma limitação e responder a uma alternativa sem alegar superioridade universal.", focus:"Justificativa metodológica e limites", intro:"Um pesquisador escolheu entrevistas semiestruturadas para entender como trabalhadores interpretam uma nova escala. Um colega pergunta por que não usar um questionário representativo. A resposta não é que entrevistas sejam “mais profundas” em qualquer projeto: cada método torna certos dados acessíveis e deixa outros fora. Defenda o alinhamento entre pergunta e método, reconheça custos de amostragem e considere triangulação quando necessária. Uma justificativa forte explica por que a alternativa não responderia a mesma pergunta com as mesmas condições.",
    phrases:[["This method was selected because it addresses how participants interpret the change.","Este método foi escolhido porque aborda como os participantes interpretam a mudança.","Relaciona método à pergunta, sem declarar que seja melhor para todos os objetivos."],["It does not estimate how common each view is across the workforce.","Ele não estima quão comum cada opinião é em toda a força de trabalho.","Limita o tipo de inferência possível."],["A survey could complement the interviews at a later stage.","Uma pesquisa poderia complementar as entrevistas numa etapa posterior.","Apresenta método alternativo como complemento condicionado, não rival absoluto."],["The sampling decision may shape which experiences are represented.","A decisão de amostragem pode influenciar quais experiências são representadas.","May calibra o efeito possível e conduz a exame de cobertura." ]],
    grammarTitle:"Justificativa, contraste e escopo inferencial", grammar:"Use the method is suited to the question of… para declarar alinhamento; it is not designed to estimate… para delimitar inferência. Whereas contrasta o que métodos permitem observar; could complement sugere combinação. Uma justificativa não prova validade: explique recrutamento, instrumentos, análise e possíveis vieses. Distingua confiabilidade, validade, representatividade e profundidade qualitativa. Avoid because it is standard: convenção não é justificativa suficiente. Se a pergunta muda, a adequação do método também pode mudar.",
    examples:[["We sampled night-shift staff because the question concerns handover after midnight.","Amostramos funcionários do turno noturno porque a pergunta trata da passagem de plantão após a meia-noite."],["The observation protocol captures task sequence, not private attitudes.","O protocolo de observação capta a sequência de tarefas, não atitudes privadas."],["A larger survey could estimate prevalence, although it would not explain every response.","Uma pesquisa maior poderia estimar prevalência, embora não explicasse cada resposta."],["We will compare interview accounts with scheduling records to examine discrepancies.","Compararemos relatos de entrevistas com registros de escala para examinar discrepâncias."]],
    practice:[["A pergunta investiga como usuários interpretam uma mensagem. Qual justificativa metodológica é melhor?",["Interviews allow participants to explain their interpretations, though they do not estimate population prevalence.","Interviews are always more scientific than surveys.","A method needs no link to the research question."],0,"Alinha método à pergunta e identifica um limite de generalização."],["Qual frase delimita o que observação direta mede?",["It records visible task sequences, not participants' private motives.","It proves why every person acted.","It captures every thought automatically."],0,"A distinção evita inferir estados internos do comportamento observado."],["Um questionário pode complementar entrevistas quando…",["the study also needs an estimate of how widespread a pattern is, with suitable sampling.","it will automatically remove all bias.","the initial method produced an inconvenient answer."],0,"Complemento depende de uma necessidade inferencial e de desenho apropriado."],["Que resposta é mais defensável à crítica de uma amostra pequena?",["It limits prevalence claims; we can report the scope and add a broader sample if that question matters.","Small samples never provide insight.","The sample is representative because we say so."],0,"A resposta reconhece limite e propõe ação proporcional à pergunta."]],takeaway:"Defenda o alinhamento entre pergunta e método, declare o tipo de inferência que não pode fazer e trate alternativas como escolhas com custos."
  },
  {
    id:"ethical-recommendations", title:"A recommendation with consequences", subtitle:"Pondere impactos e responsabilidades em uma recomendação.", objective:"Redigir recomendação que identifique beneficiários, grupos potencialmente prejudicados, condição de implementação, salvaguarda e mecanismo de revisão.", focus:"Ética aplicada e recomendações", intro:"Uma prefeitura considera usar um sistema automatizado para priorizar pedidos de manutenção. A recomendação pode acelerar casos comuns, mas dados incompletos talvez prejudiquem bairros com menos registros. Uma decisão ética não se resume a “benefício versus risco”: pergunta quem recebe o benefício, quem absorve o custo e quem pode contestar o resultado. Uma boa recomendação explicita condições, salvaguardas e monitoramento. Ela não promete eliminar todos os danos; cria meios de detectar e responder a efeitos imprevistos.",
    phrases:[["The recommendation is conditional on an accessible appeal route.","A recomendação depende da existência de um canal de recurso acessível.","Conditional on torna salvaguarda requisito, não detalhe opcional."],["We should examine who bears the cost when the system is wrong.","Devemos examinar quem arca com o custo quando o sistema erra.","Torna distribuição de impacto uma pergunta concreta."],["Residents must be able to correct inaccurate records.","Os moradores precisam poder corrigir registros imprecisos.","Must expressa requisito normativo; a autoridade e o processo devem ser explicitados."],["Review outcomes by neighborhood before expansion.","Revise os resultados por bairro antes de ampliar o sistema.","Desagregação pode revelar diferenças ocultas pela média agregada." ]],
    grammarTitle:"Condição, obrigação e agência responsável", grammar:"Use should para recomendação, must para requisito justificado e conditional on/provided that para condição de adoção. Nomeie agente responsável por monitorar e corrigir; passiva sem agente pode diluir prestação de contas. Distinga outcome previsto de safeguard e recourse. Uma recomendação ética explicita critérios de interrupção ou revisão, prazo e grupos afetados. Evite apresentar consulta como consentimento ou equidade como propriedade automática do modelo. Quando trade-offs persistem, declare quem decide e com que justificativa.",
    examples:[["The department should publish the appeal process before the tool is used.","O departamento deveria publicar o processo de recurso antes de usar a ferramenta."],["Expansion is conditional on a review of error rates across neighborhoods.","A ampliação depende de uma revisão das taxas de erro entre bairros."],["If records are disputed, a staff member—not the automated score—will make the final determination.","Se houver contestação dos registros, uma pessoa da equipe — não a pontuação automatizada — tomará a decisão final."],["The pilot should stop if residents cannot obtain a timely correction.","O piloto deveria ser interrompido se os moradores não conseguirem correção em tempo hábil."]],
    practice:[["Qual recomendação inclui condição de responsabilização?",["Expand only after publishing an appeal route and reviewing errors by neighborhood.","Deploy immediately because the average score is high.","Assume every affected resident has consented."],0,"A primeira condiciona expansão a recurso e revisão desagregada."],["Qual modal expressa obrigação mais forte?",["must","might","could possibly"],0,"Must expressa requisito, cuja justificativa e autoridade devem ser claras."],["Por que identificar quem decide recursos?",["It clarifies accountability when automated records are challenged.","It makes the process infallible.","It removes the need for review."],0,"Responsável identificado permite contestação e correção, sem garantir ausência de erro."],["Qual critério de interrupção é acionável?",["Pause the pilot if timely corrections are unavailable to affected residents.","Continue unless nobody complains.","Review only if results are embarrassing."],0,"Define condição observável e protege contra depender apenas de reclamações espontâneas."]],takeaway:"Nomeie quem se beneficia e quem pode arcar com o erro; condicione implementação a salvaguardas, responsável e revisão mensurável."
  },
  {
    id:"c2-expert-panel", title:"Expertise in conversation", subtitle:"Participe de uma discussão especializada interdisciplinar.", objective:"Participar de painel interdisciplinar explicando um termo ao público misto, qualificando uma afirmação, respondendo a uma objeção e conectando recomendações a limites e responsabilidades.", focus:"Comunicação interdisciplinar especializada", intro:"Um painel reúne engenheira, economista, profissional de saúde e representantes comunitários para discutir sensores ambientais. Cada especialidade mede algo diferente; a palavra “impacto” pode significar custo, exposição ou bem-estar. A participação C2 exige traduzir sem monopolizar, perguntar sem fingir neutralidade e diferenciar evidência de julgamento normativo. Prepare uma contribuição curta, escute o enquadramento de outras áreas e reconheça quando uma pergunta excede seus dados. O objetivo é uma decisão mais informada, não uma exibição de jargão.",
    phrases:[["In my field, ‘exposure’ refers to the measured contact, not the resulting harm.","Na minha área, ‘exposição’ se refere ao contato medido, não ao dano resultante.","Define termo e distingue variável de consequência."],["That is outside what our dataset can establish.","Isso está além do que nosso conjunto de dados pode estabelecer.","Limite explícito evita autoridade indevida."],["Could we agree on what ‘success’ means before comparing estimates?","Podemos combinar o que significa ‘sucesso’ antes de comparar estimativas?","Solicita definição operacional compartilhada."],["The recommendation also depends on who bears the implementation cost.","A recomendação também depende de quem arca com o custo de implementação.","Introduz dimensão distributiva que uma comparação técnica pode omitir." ]],
    grammarTitle:"Definição situada e limites de competência", grammar:"In my field / for this analysis delimita autoridade; does not establish / is consistent with calibra evidência. Compare estimates only after aligning definitions, units, populations and periods. Uma pergunta interdisciplinar pode pedir definição antes de objeção: When you use X, are you referring to…? Ao recomendar, separe afirmação empírica (what the data suggest) de valor (what should count as acceptable). Use I cannot speak to… para reconhecer limite e indicar quem ou qual dado poderia responder. Não use caveat como fuga: ofereça o que se pode afirmar com confiança.",
    examples:[["The cost model includes equipment but excludes long-term maintenance.","O modelo de custos inclui equipamento, mas exclui manutenção de longo prazo."],["Our measurements are consistent with higher exposure near the road; they do not show clinical outcomes.","Nossas medições são compatíveis com maior exposição perto da estrada; não mostram resultados clínicos."],["For the community group, success may also include a transparent complaint process.","Para o grupo comunitário, sucesso também pode incluir um canal transparente de reclamação."],["A clinician would be better placed to interpret the health implications of that threshold.","Uma profissional de saúde estaria mais bem posicionada para interpretar as implicações clínicas desse limite."]],
    practice:[["Um painel usa “impact” com significados diferentes. Qual intervenção é produtiva?",["Could we specify whether we mean exposure, cost, or health outcome before comparing figures?","The word is obvious, so no definition is needed.","Only my discipline can define impact."],0,"A definição compartilhada evita comparar medidas incompatíveis."],["Seu conjunto de dados mede exposição, não saúde. Como responder?",["We observed higher exposure; clinical consequences require evidence beyond this dataset.","The data prove illness.","The data are worthless."],0,"A resposta declara achado e limite, sem inflar nem descartar a evidência."],["Qual frase separa evidência empírica de julgamento normativo?",["The measurements show X; whether that level is acceptable is a policy judgment.","The measurements decide what society should value.","Values are irrelevant to recommendations."],0,"Distingue observação de decisão baseada em valores."],["Uma questão está fora da sua especialidade. Qual resposta mantém utilidade?",["I cannot interpret the clinical threshold, but I can explain what our sensor measured.","I will guess confidently.","No one should answer the question."],0,"Reconhece limite e oferece contribuição pertinente." ]],takeaway:"Defina termos entre áreas, alinhe medidas e declare o limite da sua competência enquanto contribui com o que seus dados sustentam."
  },
  {
    id:"choose-an-original-question", title:"A question only you would ask", subtitle:"Defina uma pergunta original e relevante.", objective:"Formular uma pergunta investigável que combine fenômeno, contexto e perspectiva original, justificar relevância e antecipar evidência que poderia contrariar a hipótese inicial.", focus:"Originalidade e desenho de investigação", intro:"“Does remote work improve productivity?” é ampla e traz termos disputados. Uma investigação original pode perguntar como trabalhadores de uma equipe híbrida decidem quando interromper mensagens após o expediente, e como essa prática varia por função. Originalidade não exige uma pergunta extravagante: pode residir numa conexão pouco estudada, num grupo ausente ou numa comparação mais precisa. Delimite acesso, prazo e método; depois pergunte o que poderia refutar sua expectativa. Uma pergunta de qualidade abre investigação em vez de esconder uma conclusão desejada.",
    phrases:[["The inquiry asks how staff interpret the boundary after hours.","A investigação pergunta como a equipe interpreta o limite após o expediente.","Define fenômeno experiencial sem pressupor um efeito único."],["This question matters because current guidance treats roles as interchangeable.","Esta pergunta importa porque a orientação atual trata funções como intercambiáveis.","Justificativa identifica lacuna específica a verificar, não mera alegação de novidade."],["What evidence would challenge the expectation that…?","Que evidência contestaria a expectativa de que…?","Transforma expectativa em hipótese revisável."],["The project is feasible within the available records and interview window.","O projeto é viável com os registros disponíveis e o período reservado para entrevistas.","Factibilidade depende de fontes e prazo concretos." ]],
    grammarTitle:"Perguntas abertas, delimitação e hipótese", grammar:"How do / under what conditions / to what extent definem relação e permitem respostas variadas. Delimite população, local, período e unidade de análise. A hipótese é uma expectativa testável, não a pergunta nem o resultado; formule what would count against it. Avoid why questions quando o método não identifica mecanismo causal; how/under what conditions pode ser mais adequado. Justifique relevância com lacuna documentada e contribuição possível, sem alegar “ninguém estudou” antes de busca sistemática. Confirme viabilidade, ética e dados acessíveis.",
    examples:[["How do first-year nurses interpret handover notes during night shifts?","Como enfermeiros do primeiro ano interpretam notas de passagem de plantão no turno noturno?"],["To what extent do meeting rules affect who contributes in hybrid sessions?","Até que ponto as regras de reunião afetam quem contribui em sessões híbridas?"],["If the expectation is correct, requests should cluster after the schedule change; if not, the pattern may be stable.","Se a expectativa estiver correta, os pedidos devem se concentrar após a mudança de escala; caso contrário, o padrão pode permanecer estável."],["The study will examine two teams over eight weeks, not the organization as a whole.","O estudo examinará duas equipes durante oito semanas, não a organização inteira."]],
    practice:[["Qual pergunta é delimitada e aberta a resultados diversos?",["How do two clinics communicate appointment changes to patients with limited internet access?","Is technology always harmful?","Why did the policy obviously fail everywhere?"],0,"A primeira define contexto, prática e grupo relevante sem pressupor resultado."],["O que torna uma pergunta original de modo defensável?",["A documented gap or new connection that is meaningful and feasible to investigate.","A claim that no one has ever asked anything similar.","The use of the most technical wording possible."],0,"Originalidade pede contextualização e contribuição plausível, não superlativo sem busca."],["Uma hipótese deve…",["state an expectation that evidence could support or challenge","repeat the conclusion as a question","be impossible to revise"],0,"Testabilidade pressupõe possibilidade de revisão diante de evidência."],["O método não permite inferir causa. Como revisar pergunta?",["Ask how the pattern varies or what participants report, rather than why the policy caused it.","Keep a causal claim regardless of design.","Remove the context and add certainty."],0,"A pergunta deve corresponder à capacidade inferencial do método."]],takeaway:"Delimite pergunta, contexto e evidência acessível; declare o que a contrariaria e evite prometer inferências que seu método não permite."
  },
  {
    id:"curate-a-source-collection", title:"A carefully chosen corpus", subtitle:"Selecione fontes representativas e reconheça lacunas.", objective:"Montar um conjunto de fontes justificando critérios de inclusão, diversidade de perspectiva, proveniência e lacunas, sem confundir variedade com representatividade estatística.", focus:"Curadoria de fontes e corpus", intro:"Para estudar como uma cidade descreve mobilidade, você reúne comunicados oficiais, atas, depoimentos e publicações de organizações locais. Uma coleção maior não é automaticamente melhor: pode repetir o mesmo enquadramento ou excluir vozes sem arquivo digital. Defina período, gênero e critérios antes de selecionar; registre quem produziu cada fonte, para qual público e em que condições. Um corpus qualitativo pode revelar padrões discursivos, mas não representa automaticamente toda a população. Documente ausências e explique como elas limitam a leitura.",
    phrases:[["The corpus includes documents from three institutional positions.","O corpus inclui documentos de três posições institucionais.","Nomeia cobertura, mas não garante diversidade de experiências."],["We excluded reposts to avoid counting the same statement twice.","Excluímos republicações para não contar a mesma declaração duas vezes.","Explicita regra de seleção e possível efeito sobre o corpus."],["The archive contains no material from residents without internet access.","O arquivo não contém materiais de moradores sem acesso à internet.","Lacuna de disponibilidade não equivale à ausência de opinião."],["These sources are illustrative, not statistically representative.","Estas fontes são ilustrativas, não estatisticamente representativas.","Delimita tipo de contribuição e generalização." ]],
    grammarTitle:"Critérios de inclusão, atribuição e limites", grammar:"Use included because… para tornar critério explícito; excluded from the analysis because… distingue ausência deliberada de inexistência. This collection reflects available records, not necessarily the full range of views evita generalização. Compare source types por autoria, propósito, circulação, data e incentivos. Counts of documents não equivalem a frequência de opinião na população. Registre duplicatas, idioma, acessibilidade e sobrevivência arquivística. Se a amostragem é intencional, nomeie-a; não a descreva como representativa sem desenho que sustente essa afirmação.",
    examples:[["We selected meeting minutes from the two years before and after the change.","Selecionamos atas dos dois anos anteriores e posteriores à mudança."],["The collection includes advocacy statements as well as agency responses.","A coleção inclui declarações de organizações civis e respostas da agência."],["Several neighborhood groups have no archived material in the repository.","Vários grupos de bairro não têm material arquivado no repositório."],["The sample can illustrate competing frames, but it cannot estimate how common each is.","A amostra pode ilustrar enquadramentos concorrentes, mas não estimar quão comuns são."]],
    practice:[["Você seleciona materiais de canais oficiais e organizações locais. Qual descrição é mais rigorosa?",["The corpus spans these source positions; it does not claim to represent every resident.","The corpus represents the whole city because it contains many documents.","All sources are neutral by definition."],0,"Variedade de fontes amplia perspectivas sem criar representatividade automática."],["Um arquivo não tem relatos de um grupo. Qual conclusão evitar?",["That the group had no view on the issue.","That the archive has a documented coverage gap.","That more accessible sources may dominate the corpus."],0,"Ausência arquivística não prova ausência de opinião."],["Por que excluir republicações?",["To prevent duplicate statements from distorting counts, while documenting the rule.","Because repeated views are never important.","To make the evidence agree."],0,"A deduplicação melhora contagem, mas a decisão deve ser transparente."],["Qual informação ajuda avaliar uma fonte?",["Who produced it, for whom, when, and under what purpose or constraints.","Whether its title sounds authoritative.","Whether it confirms the researcher's expectation."],0,"Proveniência, audiência, data e finalidade contextualizam a evidência."]],takeaway:"Defina inclusão antes de selecionar; descreva proveniência e lacunas e não confunda um corpus ilustrativo com amostra estatística."
  },
  {
    id:"analyze-language-and-context", title:"Language as evidence", subtitle:"Analise forma, contexto e efeito em conjunto.", objective:"Analisar uma escolha linguística citando forma, contexto e efeito possível, distinguir padrão recorrente de ocorrência isolada e confrontar uma interpretação alternativa.", focus:"Análise discursiva contextual", intro:"Num conjunto de comunicados, a agência descreve atrasos como “unavoidable” e mudanças como “necessary”. Esses adjetivos podem normalizar decisões, mas uma ocorrência não prova um padrão deliberado. Examine quem fala, em que gênero, para qual audiência e com que alternativas lexicais. Compare frequência e distribuição, além de documentos de resposta. Uma análise precisa conecta forma e efeito possível, sem transformar interpretação em intenção certa. Quando outra leitura plausível existir, explique qual contexto ajudaria a distingui-las.",
    phrases:[["The repeated adjective presents the delay as beyond control.","O adjetivo recorrente apresenta o atraso como fora de controle.","Repeated exige recorrência observada; presents descreve efeito potencial."],["In this context, ‘necessary’ leaves the decision-maker unstated.","Neste contexto, ‘necessário’ deixa sem nome quem tomou a decisão.","A observação gramatical deve ser demonstrada pela construção específica."],["One occurrence is not enough to establish a pattern.","Uma ocorrência não basta para estabelecer um padrão.","Delimita nível de evidência discursiva."],["An alternative reading is that the term follows a standard reporting template.","Uma leitura alternativa é que o termo segue um modelo padrão de relatório.","Oferece explicação concorrente que pode ser verificada documentalmente." ]],
    grammarTitle:"Forma linguística, contexto e inferência", grammar:"Analise palavra ou estrutura observável (passiva, modalidade, metáfora, nominalização), localização no gênero e efeito plausível. Quantifique padrões com denominador e comparação apropriados; frequência isolada não prova intenção nem influência sobre leitores. Distinga “the wording foregrounds X” (efeito interpretativo argumentado) de “the author intended X” (alegação de intenção). Compare documentos, versões e respostas. Use may position, can imply ou is consistent with para calibrar. A interpretação deve explicar tanto o dado quanto as exceções, não só selecionar exemplos convenientes.",
    examples:[["Across four notices, ‘temporary’ appears without a stated end date.","Em quatro avisos, ‘temporário’ aparece sem uma data final indicada."],["The passive construction centers the delay while omitting who authorized it.","A construção passiva põe o atraso em foco e omite quem o autorizou."],["The template may explain the repeated wording, though not its effect on readers.","O modelo pode explicar a formulação repetida, embora não seu efeito sobre leitores."],["A later revision names the decision-maker and adds an end date.","Uma revisão posterior nomeia quem tomou a decisão e acrescenta uma data final."]],
    practice:[["Você encontra “temporary” em um único aviso. Qual conclusão é proporcional?",["This occurrence uses the term; more examples are needed to claim a recurring pattern.","The agency always hides permanent decisions.","The word has no possible effect."],0,"Uma ocorrência apoia descrição local, não padrão nem intenção recorrente."],["Qual análise liga forma e contexto sem afirmar intenção?",["The passive centers the postponement; the notice does not identify the authorizing office.","The writer deliberately concealed the truth.","Passives are always deceptive."],0,"Descreve estrutura e informação ausente sem atribuir motivo."],["Uma hipótese alternativa é uso de template. O que investigar?",["Compare other notices and template versions from the same period.","Ignore all documents that complicate the claim.","Assume templates have no effects."],0,"Comparação documental testa a explicação concorrente."],["Qual afirmativa distingue efeito de propósito?",["The wording can make the decision appear routine; evidence of intent would require more than the phrasing alone.","The wording proves the author's private motive.","Readers must interpret it identically."],0,"Separa efeito argumentado de intenção psicológica não demonstrada."]],takeaway:"Cite forma e contexto, demonstre recorrência com comparação e mantenha efeito possível separado de intenção atribuída."
  },
  {
    id:"develop-a-subtle-thesis", title:"A thesis that leaves room", subtitle:"Defenda uma tese precisa sem simplificar tensões.", objective:"Redigir tese que faça uma afirmação interpretativa clara, delimite escopo, integre uma tensão relevante e indique o que a evidência ainda não permite concluir.", focus:"Tese nuançada e tensão argumentativa", intro:"Uma análise de avisos públicos encontra mensagens mais claras após revisão, mas algumas continuam inacessíveis em dispositivos antigos. “A revisão resolveu o problema” é ampla demais; “nada melhorou” ignora o avanço. Uma tese sutil não é indecisa: afirma algo definido e explica sob quais condições, para quem e com que ressalva. A tensão é parte do argumento, não uma nota de rodapé. Escreva uma versão curta, destaque o verbo que expressa sua interpretação e teste se cada evidência contribui para sustentá-la.",
    phrases:[["The revision improved clarity for most users, though access remains uneven.","A revisão melhorou a clareza para a maioria dos usuários, embora o acesso continue desigual.","A tese combina achado e limite sem os tornar mutuamente excludentes."],["This pattern is strongest in the newer-device sample.","Esse padrão é mais forte na amostra de dispositivos recentes.","Delimita onde a interpretação recebe mais suporte."],["The evidence supports a qualified claim rather than a universal one.","As evidências sustentam uma afirmação qualificada, não universal.","Qualified identifica a força calibrada da tese."],["The remaining gap changes how the recommendation should be implemented.","A lacuna restante muda como a recomendação deveria ser implementada.","Conecta ressalva a consequência prática, em vez de apenas adicioná-la." ]],
    grammarTitle:"Tese, concessão e escopo", grammar:"Uma tese analítica pode usar although/while para integrar tensão e only/among/in this sample para limitar alcance. The evidence suggests that é útil quando a conclusão é inferencial; shows pode ser apropriado para observação direta, não automaticamente para causalidade. Evite both sides language se o suporte é assimétrico. A ressalva precisa alterar escopo, confiança ou recomendação; se não, talvez seja periférica. Garanta que referência como this gap nomeie antecedente claro. Releia a tese após selecionar evidências para que permaneça revisável.",
    examples:[["Although response times improved, the gains were concentrated in offices with stable internet access.","Embora os tempos de resposta tenham melhorado, os ganhos se concentraram em escritórios com internet estável."],["The interviews suggest that clearer labels helped, but they do not establish a long-term effect.","As entrevistas sugerem que rótulos mais claros ajudaram, mas não estabelecem efeito de longo prazo."],["Among the sites studied, the smallest clinic benefited most from a paper fallback.","Entre os locais estudados, a clínica menor se beneficiou mais de uma alternativa em papel."],["The recommendation should retain the fallback because the access gap remains material.","A recomendação deveria manter a alternativa porque a lacuna de acesso continua relevante."]],
    practice:[["Qual tese integra um achado e uma ressalva importante?",["The revised notices improved response time in connected sites, while offline access remains unresolved.","The notices solved every access problem.","Nothing changed in any respect."],0,"A primeira sustenta melhoria delimitada e preserva questão aberta."],["Qual ressalva altera de fato a recomendação?",["Keep a paper route because some users cannot access the digital form.","The report was written on a Tuesday.","The topic is complicated."],0,"A limitação de acesso implica uma salvaguarda específica."],["Complete a tese cautelosa: “The interviews ___ that clearer labels helped.”",["suggest","guarantee","prove universally"],0,"Suggest calibra uma inferência de entrevistas sem transformar relato em prova universal."],["Uma evidência contradiz parte da tese. O que fazer?",["Revise the scope or claim and explain the tension.","Omit the evidence automatically.","Keep the original conclusion unchanged."],0,"Tese analítica deve responder a evidência contrária e ajustar alcance se necessário."]],takeaway:"Declare o achado, delimite onde se aplica e incorpore a ressalva que muda a interpretação ou a ação recomendada."
  },
  {
    id:"c2-inquiry-conference", title:"Presenting an independent inquiry", subtitle:"Apresente pesquisa e responda a questionamentos críticos.", objective:"Apresentar uma investigação original em cinco minutos, situando pergunta, corpus, método, achado, limite e contribuição, e responder a uma objeção sem extrapolar evidência.", focus:"Apresentação de pesquisa e resposta crítica", intro:"Na conferência, sua pesquisa sobre avisos multilíngues é questionada: “How do you know the wording, rather than staffing, changed response times?” Você precisa acolher a questão, dizer o que o desenho distingue e não distingue e mostrar por que a análise ainda é útil. Uma apresentação de pesquisa não é leitura de relatório: seleciona uma linha de raciocínio para o tempo e a audiência. Prepare estrutura flexível, sinalize quando está respondendo à pergunta e retorne à tese com o limite incorporado.",
    phrases:[["The inquiry asks how readers interpret the revised notice.","A investigação pergunta como leitores interpretam o aviso revisado.","Abre com pergunta e não com resultado pressuposto."],["Our corpus comprises twelve notices and follow-up interviews at two sites.","Nosso corpus reúne doze avisos e entrevistas de acompanhamento em dois locais.","Resume fontes e escopo verificáveis."],["The design cannot isolate wording from staffing changes.","O desenho não consegue isolar a formulação das mudanças de equipe.","Declara limite causal de modo direto."],["The contribution is to identify where interpretation diverges, not to estimate a citywide effect.","A contribuição é identificar onde as interpretações divergem, não estimar um efeito em toda a cidade.","Define contribuição no nível compatível com o método."]],
    grammarTitle:"Roteiro oral e resposta a perguntas", grammar:"Sinalize moves: My question is…, We examined…, The pattern suggests…, A limitation is…, The contribution is… . Para uma objeção, paraphrase first (You’re asking whether staffing could explain the change), then answer what evidence can address and name what remains unresolved. Use I cannot infer X from this design, but I can show Y to evitar resposta evasiva. Se a pergunta tiver duas partes, separe-as. Retome o fio com To return to the main finding… sem ignorar o questionamento. Não esconda limites em fala acelerada ou em slide final ilegível.",
    examples:[["To answer the staffing question, we compared sites where the staffing model did not change.","Para responder à questão da equipe, comparamos locais onde o modelo de pessoal não mudou."],["That comparison reduces one alternative explanation but does not eliminate all confounding.","Essa comparação reduz uma explicação alternativa, mas não elimina todos os fatores de confusão."],["The interviews show differing interpretations of the same instruction.","As entrevistas mostram interpretações diferentes da mesma instrução."],["A larger controlled study would be needed to estimate a causal effect.","Seria necessário um estudo controlado maior para estimar um efeito causal."]],
    practice:[["Uma pergunta desafia causalidade. Qual resposta é intelectualmente honesta e útil?",["We compared stable-staffing sites, which addresses one alternative; the design still cannot establish causation.","Staffing cannot matter because we studied wording.","The results prove the claim universally."],0,"Reconhece análise parcial e limite remanescente."],["Qual abertura de resposta mostra que você entendeu a objeção?",["You’re asking whether the staffing change could explain the timing difference.","That is irrelevant.","I will repeat my slide."],0,"Paráfrase especifica a questão e permite correção."],["Em uma apresentação de cinco minutos, o que deve receber prioridade?",["Question, method, central finding, limitation, and contribution.","Every detail in the source archive.","A long biography before the research question."],0,"A estrutura preserva linha de raciocínio e escopo no tempo disponível."],["Como retornar à tese após responder uma pergunta?",["To return to the main finding, the interviews reveal two distinct readings.","Anyway, the question does not matter.","Pretend the interruption never happened."],0,"A transição retoma o argumento sem desconsiderar a pergunta."]],takeaway:"Apresente pergunta, método, achado e limite; ao responder, reformule a objeção e diga precisamente o que seu desenho pode e não pode sustentar."
  },
  {
    id:"plan-a-multigenre-portfolio", title:"One inquiry, several forms", subtitle:"Planeje gêneros distintos para uma mesma investigação.", objective:"Planejar portfólio com três gêneros para públicos definidos, mapear núcleo factual compartilhado e especificar como cada gênero adapta estrutura sem alterar evidência ou grau de certeza.", focus:"Portfólio multimodal e adaptação", intro:"Uma investigação sobre calor em escolas precisa chegar a gestores, famílias e pesquisadores. O relatório técnico detalha método e dados; um folheto explica ações imediatas; uma apresentação pública abre diálogo e registra dúvidas. Criar versões não é duplicar o mesmo texto nem alterar os fatos para persuadir cada audiência. Planeje primeiro o núcleo invariável — achados, escopo, limite e fonte — e depois o trabalho de cada gênero. Considere acessibilidade, tradução, canal de distribuição e como o público poderá responder.",
    phrases:[["The core finding remains the same across all three formats.","O achado central permanece o mesmo nos três formatos.","Define núcleo factual a preservar."],["The public brief foregrounds actions residents can take.","O resumo público põe em primeiro plano ações que moradores podem tomar.","Adapta prioridade sem esconder achado ou limite."],["The technical appendix documents the sampling decisions.","O apêndice técnico documenta decisões de amostragem.","Aloca detalhe ao gênero apropriado e mantém rastreabilidade."],["Each version should state where the evidence is limited.","Cada versão deve indicar onde as evidências são limitadas.","A ressalva é parte do núcleo comum, não detalhe dispensável." ]],
    grammarTitle:"Movimentos retóricos por gênero", grammar:"Mapeie audiência → finalidade → ação → detalhe necessário. Imperativos podem ser apropriados num aviso operacional; hedges e método são essenciais em relatório; perguntas e pausas favorecem apresentação dialogada. Use the same evidence indicates… como âncora; adapte explicação e ordem. Não remova o qualificador (in two schools, during July) na versão curta se isso mudar o alcance. Text alternatives, captions e contraste são parte da comunicação, não adereços. Planeje versões e revisão com representantes do público, especialmente quando decisões os afetam.",
    examples:[["Public brief: Keep classrooms ventilated during the hottest hours where safe to do so.","Resumo público: Mantenha as salas ventiladas nas horas mais quentes, quando for seguro."],["Technical report: Measurements from four rooms suggest uneven afternoon exposure.","Relatório técnico: Medições de quatro salas sugerem exposição desigual à tarde."],["Presentation: We found variation across rooms; what barriers make the recommended step difficult?","Apresentação: Encontramos variação entre salas; que barreiras dificultam a medida recomendada?"],["All versions note that the sample covers one school and one month.","Todas as versões observam que a amostra cobre uma escola e um mês."]],
    practice:[["Qual plano mantém a integridade entre gêneros?",["Keep findings and scope fixed; adapt order, explanation, and call to action to each audience.","Make the result stronger in the public version to gain attention.","Remove method and limits from every short format."],0,"A adaptação muda apresentação, não força ou alcance da evidência."],["O relatório cobre uma escola. O que deve constar também no folheto?",["A concise indication that the finding comes from one school.","A claim about every school in the region.","No context, because the format is short."],0,"Brevidade não justifica generalização indevida."],["Qual formato pode facilitar diálogo?",["A presentation with time for questions and a way to record unresolved concerns.","A one-way announcement with no response channel.","A technical appendix alone."],0,"Formato dialogado permite perguntas e registro de lacunas."],["Como testar acessibilidade do portfólio?",["Check captions, readable structure, language access, and the intended channels with users.","Assume one format works for everyone.","Use smaller text to fit more content."],0,"Acessibilidade precisa ser verificada em dimensões e canais relevantes."]],takeaway:"Fixe fatos, escopo e ressalvas antes de adaptar; dê a cada gênero um propósito claro e teste acesso com o público previsto."
  },
  {
    id:"write-with-control-and-range", title:"A final written contribution", subtitle:"Produza texto de alta precisão e voz consistente.", objective:"Escrever contribuição final com tese original, progressão coesa, variedade sintática controlada, atribuição rastreável e ressalvas integradas à conclusão.", focus:"Escrita C2, voz e precisão", intro:"Sua contribuição final deve ser lida por especialistas e por pessoas afetadas pela decisão. O texto precisa ter voz própria, mas não transformar complexidade em opacidade. Variedade sintática serve para estabelecer hierarquia e ritmo; léxico preciso evita ambiguidade; transições demonstram relações reais. Escreva primeiro para que o argumento seja examinável e só depois refine a superfície. Revise cada verbo de certeza, cada pronome de referência e cada atribuição. A elegância está em fazer trabalho intelectual complexo parecer claro sem o tornar simplista.",
    phrases:[["The central claim is narrower than the policy question it informs.","A afirmação central é mais delimitada que a questão de política pública que informa.","Distingue tese do campo decisório maior."],["The comparison is informative, albeit constrained by the available records.","A comparação é informativa, embora limitada pelos registros disponíveis.","Albeit introduz ressalva concisa; o limite deve ser especificado em seguida."],["This distinction matters because the two measures answer different questions.","Essa distinção importa porque as duas medidas respondem a perguntas diferentes.","This distinction retoma antecedente nomeado e explica relevância."],["The conclusion follows only if the access condition is met.","A conclusão só se sustenta se a condição de acesso for atendida.","Only if restringe validade e torna a condição visível." ]],
    grammarTitle:"Variedade sintática sob controle", grammar:"Alterne períodos simples para afirmações centrais e períodos complexos para relações condicionais ou concessivas. Uma oração concessiva pode estabelecer nuance; uma oração relativa deve ter antecedente inequívoco. Fronting e inversão são opções, não marcadores automáticos de sofisticação. Prefira verbo preciso a nominalizações em cadeia; use voz passiva quando agente é desconhecido ou irrelevante, ativa quando responsabilidade importa. Atribua paráfrases e citações, preserve escopo da fonte e mantenha coerência terminológica. Faça leitura em voz alta e reduza frases cujo encadeamento excede a memória de trabalho do leitor.",
    examples:[["The archive is incomplete. That limitation affects whose experiences can be reconstructed.","O arquivo é incompleto. Essa limitação afeta quais experiências podem ser reconstruídas."],["Although the estimate is stable across the two sites, it should not be generalized beyond them.","Embora a estimativa seja estável nos dois locais, não deve ser generalizada para além deles."],["The committee changed the eligibility rule after receiving the appeal; the minutes record no reason.","A comissão alterou a regra de elegibilidade após receber o recurso; a ata não registra a razão."],["Only with a comparable follow-up can we assess whether the pattern persists.","Só com acompanhamento comparável poderemos avaliar se o padrão persiste."]],
    practice:[["Qual edição melhora referência e coesão?",["The archive is incomplete. This gap limits whose accounts can be included.","This affects that, which matters because it changed.","The archive is incomplete, and therefore the committee is wrong."],0,"This gap nomeia o referente e explicita consequência sem salto lógico."],["Qual frase reserva inversão para um foco retórico claro?",["Only after the second review did the team identify the missing category.","Only the second review did identify the missing category always.","Did only review the team category."],0,"Only after no início da oração principal licencia inversão correta."],["Como decidir entre ativa e passiva?",["Use active voice when the responsible agent matters; use passive when the event or result is the focus.","Use passive to make every statement objective.","Use active only in informal writing."],0,"A escolha organiza foco e transparência conforme a relevância do agente."],["Uma fonte sustenta resultado em dois locais. Qual conclusão é mais precisa?",["The pattern held in the two sites; broader settings require further evidence.","The pattern holds everywhere.","The source proves nothing at all."],0,"Mantém escopo observado e indica evidência necessária para generalizar."]],takeaway:"Revise cada frase por função: tese, evidência, relação ou limite; mantenha referências claras e controle a força dos verbos."
  },
  {
    id:"present-with-adaptive-fluency", title:"A conversation, not a script", subtitle:"Apresente ideias e adapte a exposição ao diálogo.", objective:"Apresentar uma ideia central com estrutura flexível, responder a interrupções e perguntas com síntese e reformulação, e retomar o fio sem abandonar precisão ou naturalidade.", focus:"Fluência adaptativa e interação", intro:"Você apresenta uma recomendação a um conselho. Uma pergunta interrompe o segundo slide; alguém pede definição de “equitable”; outra pessoa contesta o custo. Um texto decorado pode falhar quando a conversa sai da sequência prevista. Fluência avançada inclui ouvir, selecionar o que responder, pedir esclarecimento e alterar a explicação sem perder a tese. Não significa falar sem pausa. Uma pausa para pensar, uma resposta direta e uma retomada bem sinalizada podem soar mais competentes que improvisação contínua.",
    phrases:[["Let me answer the cost question first, then I’ll return to the comparison.","Vou responder primeiro à questão do custo e depois retomo a comparação.","Organiza desvio e retomada, mostrando que a pergunta foi ouvida."],["By ‘equitable’, I mean that access barriers are identified and addressed.","Por ‘equitativo’, quero dizer que barreiras de acesso são identificadas e enfrentadas.","Define termo para esta proposta, sem reivindicar definição universal."],["I need a moment to distinguish two parts of that question.","Preciso de um momento para distinguir duas partes dessa pergunta.","Pausa explícita permite resposta estruturada em vez de hesitação opaca."],["The short answer is no; the qualification is that the pilot covered only two sites.","A resposta curta é não; a ressalva é que o piloto cobriu apenas dois locais.","Resposta direta seguida de limite relevante." ]],
    grammarTitle:"Sinalização oral, autocorreção e retomada", grammar:"Use the short answer is… para orientação, what I mean by… para definição, let me rephrase para autocorreção e returning to… para retomada. Se a pergunta tiver pressuposto duvidoso, responda condicionalmente: If by X you mean Y, then…; otherwise… . Marque quando não sabe: I don’t have that figure with me; I can confirm it after the session. Reformule sem pedir desculpas por cada pausa. A fluência adaptativa preserva intenção e interlocutor, não um roteiro palavra por palavra. Não responda a pergunta diferente só porque é mais fácil.",
    examples:[["The short answer is that the pilot reduced processing time in one office.","A resposta curta é que o piloto reduziu o tempo de processamento em um escritório."],["If by ‘cost’ you mean staff time, we have an estimate; total lifecycle cost is still unknown.","Se por ‘custo’ você quer dizer tempo da equipe, temos uma estimativa; o custo total do ciclo de vida ainda é desconhecido."],["I do not have the subgroup figure here, so I will not guess.","Não tenho aqui o número do subgrupo, então não vou adivinhar."],["Returning to the recommendation, it remains conditional on an accessible appeal process.","Retomando a recomendação, ela continua condicionada a um processo de recurso acessível."]],
    practice:[["Você não tem uma estatística solicitada. Qual resposta mantém credibilidade?",["I don't have that figure here; I can verify it and follow up after the meeting.","The number is probably 80%, though I am guessing.","The question is irrelevant."],0,"A primeira admite limite e oferece próximo passo verificável."],["Uma pergunta combina duas questões. O que fazer?",["Separate the parts and answer each in turn.","Ignore one without saying so.","Repeat the entire presentation."],0,"Decompor perguntas compostas reduz risco de resposta incompleta."],["Você precisa voltar ao argumento após uma resposta. Qual transição ajuda?",["Returning to the comparison, the two sites differed in access conditions.","Anyway, none of that matters.","Pretend the question was never asked."],0,"A primeira sinaliza retomada e liga ao ponto anterior."],["Qual resposta é direta e qualificada?",["No, the pilot did not include rural sites; its findings therefore do not establish rural access.","The pilot was interesting and many things are possible.","Yes, it covers every setting."],0,"Começa com resposta clara e delimita inferência do piloto."]],takeaway:"Ouça a pergunta, responda ao ponto, sinalize limites e retome o fio; peça tempo quando precisar pensar em vez de improvisar dados."
  },
  {
    id:"reflect-on-language-choices", title:"Why these words?", subtitle:"Explique escolhas de registro, estilo e evidência.", objective:"Justificar escolhas de linguagem em uma peça própria por audiência, efeito pretendido e suporte, e identificar ao menos uma alternativa que mudaria tom ou alcance.", focus:"Metalinguagem e revisão reflexiva", intro:"Uma banca pergunta por que você escreveu “may indicate” em vez de “shows”, escolheu a voz passiva numa frase e usou “residents” em vez de “service users”. A reflexão não é defesa automática de cada escolha: é capacidade de apontar efeito, alternativa e consequência. Algumas decisões são deliberadas; outras refletem convenção ou hábito. Revise com abertura para evidência e feedback, sobretudo quando uma palavra pode excluir um grupo ou atribuir agência de modo inadequado. Explique a intenção, mas não a confunda com o efeito que leitores realmente tiveram.",
    phrases:[["I chose ‘may indicate’ because the comparison is suggestive, not conclusive.","Escolhi ‘pode indicar’ porque a comparação é sugestiva, não conclusiva.","Justifica modalização pela força disponível da evidência."],["The passive keeps the outcome in focus; I name the agency elsewhere.","A passiva mantém o resultado em foco; nomeio a agência em outro trecho.","Explica escolha e mostra que omissão local não apaga responsabilidade do texto inteiro."],["I used ‘residents’ because the policy applies beyond current service users.","Usei ‘moradores’ porque a política se aplica além dos usuários atuais do serviço.","Relaciona rótulo à população relevante; deve ser confirmado pelo escopo real."],["A reader's response may differ from the effect I intended.","A reação do leitor pode diferir do efeito que eu pretendia.","Distingue intenção autoral e recepção observada." ]],
    grammarTitle:"Linguagem para justificar e revisar escolhas", grammar:"Use I chose X because… para intenção; X may lead readers to… para efeito hipotético; feedback suggests readers interpreted it as… para evidência de recepção. Compare alternative wording and specify what would change: certainty, agency, register, inclusiveness or scope. Avoid claiming “I used it to be objective” without explaining convention and effect. Modal verbs must align with evidence; labels should align with eligibility and lived categories. Reflexão madura admite trade-offs and revisions. Não declare que uma escolha foi deliberada se foi hábito; a revisão posterior ainda pode ser deliberada e responsável.",
    examples:[["I replaced ‘the vulnerable’ with ‘people facing barriers’ to avoid treating a diverse group as a fixed identity.","Troquei ‘os vulneráveis’ por ‘pessoas que enfrentam barreiras’ para não tratar um grupo diverso como identidade fixa."],["The verb ‘caused’ was too strong for our observational design, so I used ‘was associated with’. ","O verbo ‘caused’ era forte demais para nosso desenho observacional, então usei ‘was associated with’."],["I intended the heading to reassure; reader feedback showed that it sounded dismissive.","Eu pretendia tranquilizar com o título; o feedback mostrou que ele soou desdenhoso."],["The alternative would be shorter, but it would omit the condition on which the finding depends.","A alternativa seria mais curta, mas omitiria a condição da qual o achado depende."]],
    practice:[["Uma escolha verbal excede o desenho do estudo. Qual reflexão é mais responsável?",["‘Caused’ overstates the observational evidence; ‘was associated with’ better matches what we measured.","I chose ‘caused’ because it sounds decisive.","Readers should accept my wording without question."],0,"Liga verbo a evidência observada e considera alternativa precisa."],["Você pretendia tranquilizar, mas leitores relataram sentir-se descartados. Qual resposta reconhece diferença?",["My intention was reassurance; the feedback suggests the wording had a dismissive effect, so I will revise it.","They misunderstood, so no revision is needed.","My intention proves the effect was positive."],0,"Distingue intenção e recepção e usa feedback como base para revisão."],["Qual justificativa para voz passiva é mais completa?",["It foregrounds the result here; the responsible decision-maker is named in the next sentence.","Passive voice is always objective.","I wanted to hide who made the decision."],0,"Explica função local e preserva responsabilização no texto."],["Como avaliar uma alternativa mais curta?",["Check whether it preserves the condition and scope that make the claim accurate.","Prefer brevity regardless of meaning.","Assume longer wording is always more nuanced."],0,"Concisão só é ganho se não apagar distinções essenciais."]],takeaway:"Explique escolha por efeito e evidência, compare uma alternativa e trate a reação do leitor como dado que pode exigir revisão."
  },
  {
    id:"c2-final-reflection", title:"A lifelong language practice", subtitle:"Avalie registro, clareza e próximos desafios.", objective:"Avaliar o próprio repertório com evidências de desempenho, identificar uma lacuna prioritária e estabelecer plano de prática com tarefa, frequência, critério de progresso e revisão.", focus:"Autonomia, monitoramento e prática contínua", intro:"Concluir um percurso C2 não significa nunca hesitar, nem dominar toda variedade, gênero ou área especializada. Significa conseguir operar com flexibilidade e reconhecer quando o contexto exige pesquisa, esclarecimento ou colaboração. Releia textos e gravações de diferentes momentos; procure exemplos observáveis de precisão, adaptação e reparo, não apenas uma sensação global de confiança. Escolha uma lacuna que importe para seus objetivos reais e desenhe prática sustentável. O plano deve incluir feedback e oportunidade de revisar, não uma meta vaga de “estudar mais”.",
    phrases:[["I can now distinguish a claim from the inference drawn from it.","Agora consigo distinguir uma afirmação da inferência extraída dela.","Descreve competência com verbo observável."],["My next priority is handling rapid turn-taking in mixed-accent discussions.","Minha próxima prioridade é lidar com turnos rápidos em conversas com sotaques variados.","Especifica cenário que pode orientar prática."],["I will review one recorded discussion each week and note repair strategies.","Vou revisar uma conversa gravada por semana e anotar estratégias de reparo.","Plano mensurável; gravação deve respeitar consentimento e privacidade."],["I will reassess the goal after six weeks using the same task rubric.","Reavaliarei a meta após seis semanas usando a mesma rubrica de tarefa.","Critério repetido permite comparação, embora não elimine variações de desempenho." ]],
    grammarTitle:"Reflexão baseada em evidências e metas condicionais", grammar:"Use I can now… para competência demonstrável; I still find it difficult to… para lacuna; I will practise by… para ação. Defina indicador observável, contexto e prazo. Present perfect pode relacionar experiência acumulada à capacidade atual (I have become more precise), mas ancore a avaliação em exemplos. Se uma meta depender de acesso a interlocutores, declare alternativa. Reavalie com tarefa comparável e feedback externo; progresso linguístico é irregular e específico por domínio. Uma lacuna identificada não invalida a competência já desenvolvida.",
    examples:[["In my last presentation, I answered a challenge by narrowing the claim and naming the missing evidence.","Na minha última apresentação, respondi ao questionamento restringindo a tese e indicando a evidência faltante."],["I still need time to interpret unfamiliar humor in written messages.","Ainda preciso de tempo para interpretar humor desconhecido em mensagens escritas."],["Twice a month, I will summarize an unfamiliar article for a non-specialist listener.","Duas vezes por mês, resumirei um artigo desconhecido para alguém não especialista."],["If live practice is unavailable, I will annotate a recorded interview and compare my interpretation with a transcript.","Se não houver prática ao vivo, anotarei uma entrevista gravada e compararei minha interpretação com a transcrição."]],
    practice:[["Qual autoavaliação oferece evidência observável?",["In two recent discussions, I clarified a term before disagreeing with the conclusion.","My English is perfect now.","I feel that everything is easy."],0,"A primeira cita comportamento e contexto verificáveis, sem declarar domínio absoluto."],["Qual meta é mais acionável?",["Practise one five-minute explanation weekly and ask a listener to note unclear references.","Improve all English soon.","Read more whenever possible."],0,"Define frequência, tarefa e tipo de feedback."],["Por que repetir a mesma rubrica após seis semanas?",["It makes changes easier to compare, though performance can still vary by task and context.","It guarantees objective measurement.","It removes the need for feedback."],0,"Comparabilidade ajuda, mas não elimina variação ou limites da medida."],["Você não tem acesso a conversas ao vivo. Qual alternativa mantém a meta?",["Analyze a consented recording or transcript and compare interpretations with a reliable key.","Pretend the practice happened.","Abandon every goal that needs interaction."],0,"Alternativa mantém habilidade em foco e respeita consentimento e acesso." ]],takeaway:"Escolha uma competência observável, pratique em frequência sustentável, recolha feedback e reavalie com a mesma tarefa sem exigir perfeição."
  },
];

